CREATE TABLE authz_int.shared_relations (object_type text, relation text, subject text, shared_by text, required text[], loc text, PRIMARY KEY (object_type, relation, subject));

INSERT INTO authz_int.shared_relations VALUES
  ('team', 'member', 'team#member', 'share', ARRAY[]::text[], 'share team.member team#member'),
  ('folder', 'viewer', 'user', 'share', ARRAY['view']::text[], 'share folder.viewer user'),
  ('folder', 'viewer', 'team#member', 'share', ARRAY['view']::text[], 'share folder.viewer team#member'),
  ('folder', 'viewer', 'bot', 'share', ARRAY['view']::text[], 'share folder.viewer bot'),
  ('folder', 'viewer', 'bot:*', 'share', ARRAY['view']::text[], 'share folder.viewer bot:*');

DO $w$
DECLARE n bigint;
BEGIN
  SELECT count(*) INTO n FROM authz.shares g WHERE g.relation NOT LIKE 'role:%' AND NOT EXISTS (
    SELECT 1 FROM authz_int.shared_relations s WHERE s.object_type = g.object_type AND s.relation = g.relation
      AND s.subject = CASE WHEN g.subject_type IN ('anyone', 'link') THEN g.subject_type
                           WHEN g.subject_id = '*' AND g.subject_relation = '' THEN g.subject_type || ':*'
                           WHEN g.subject_relation <> '' THEN g.subject_type || '#' || g.subject_relation
                           ELSE g.subject_type END);
  IF n > 0 THEN
    RAISE WARNING '% shares are for relations this policy does not declare as shared; they are kept, but grant nothing', n;
  END IF;
END $w$;

CREATE TABLE authz_int.role_subjects (object_type text, subject text, PRIMARY KEY (object_type, subject));

CREATE TABLE authz_int.role_grantable (object_type text, permission text, PRIMARY KEY (object_type, permission));

CREATE TABLE authz_int.caveats (name text PRIMARY KEY);

-- per-type indexes on share ids, for lookups by object
DO $gi$
DECLARE i record;
BEGIN
  FOR i IN SELECT c.relname FROM pg_index x JOIN pg_class c ON c.oid = x.indexrelid
           WHERE x.indrelid = 'authz.shares'::regclass AND (c.relname LIKE 'shares\_obj\_%' OR c.relname LIKE 'grants\_obj\_%')
             AND c.relname <> ALL (ARRAY['shares_obj_user_bigint', 'shares_obj_bot_bigint', 'shares_obj_org_bigint']::text[]) LOOP
    EXECUTE format('DROP INDEX authz.%I', i.relname);
  END LOOP;
END $gi$;
CREATE INDEX IF NOT EXISTS "shares_obj_user_bigint" ON authz.shares ((object_id::bigint), relation) WHERE object_type = 'user';
CREATE INDEX IF NOT EXISTS "shares_obj_bot_bigint" ON authz.shares ((object_id::bigint), relation) WHERE object_type = 'bot';
CREATE INDEX IF NOT EXISTS "shares_obj_org_bigint" ON authz.shares ((object_id::bigint), relation) WHERE object_type = 'org';

-- Scopes: what a token may do (policy 'scope' lines; 'read' is built in unless redefined)
CREATE TABLE authz_int.scope_items (scope text, kind text, qual text, word text);
INSERT INTO authz_int.scope_items VALUES
  ('read', 'cmd', NULL, 'select'),
  ('read', 'perm', NULL, '*');

-- the scopes this transaction is limited to (NULL: not limited); believed only if signed, like the user
CREATE FUNCTION authz_int.scopes_active() RETURNS text[]
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
  SELECT CASE WHEN NOT authz_int.session_ok() THEN ARRAY[]::text[]
              WHEN coalesce(current_setting('authz.scopes', true), '') = '' THEN NULL
              ELSE ARRAY(SELECT btrim(x) FROM unnest(string_to_array(current_setting('authz.scopes', true), ',')) x
                         WHERE btrim(x) <> '') END $f$;
-- may this transaction run a command on a table?
CREATE FUNCTION authz_int.scope_cmd(p_table text, p_cmd text) RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
  SELECT s IS NULL OR EXISTS (SELECT 1 FROM authz_int.scope_items i WHERE i.scope = ANY (s) AND i.kind = 'cmd'
                              AND i.word = p_cmd AND (i.qual IS NULL OR i.qual = p_table))
  FROM (SELECT authz_int.scopes_active() AS s) x $f$;
-- may this transaction ask about (or use) a permission?
CREATE FUNCTION authz_int.scope_perm(p_type text, p_perm text) RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
  SELECT s IS NULL OR EXISTS (SELECT 1 FROM authz_int.scope_items i WHERE i.scope = ANY (s) AND i.kind = 'perm'
                              AND (i.word = p_perm OR i.word = '*') AND (i.qual IS NULL OR i.qual = p_type))
  FROM (SELECT authz_int.scopes_active() AS s) x $f$;
-- may this transaction change anything? (not while viewing as someone, not with read-only scopes)
CREATE FUNCTION authz_int.writable() RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
  SELECT coalesce(current_setting('authz.acting_user', true), '') = ''
     AND (s IS NULL OR EXISTS (SELECT 1 FROM authz_int.scope_items i WHERE i.scope = ANY (s) AND i.kind = 'cmd'
                               AND i.word <> 'select'))
  FROM (SELECT authz_int.scopes_active() AS s) x $f$;
CREATE FUNCTION authz_int.check_writable() RETURNS void
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
BEGIN
  IF NOT authz_int.writable() THEN
    RAISE EXCEPTION 'this session is read-only (viewing as someone else, or a read-only token)'
      USING ERRCODE = 'insufficient_privilege', HINT = 'rowstile help AZ704';
  END IF;
END $f$;
-- custom roles, access requests, access reviews, break-glass, a key of one's own and view-as are for users: a
-- service signed in (another principal type) is refused, saying so, even one the policy gives the permission the
-- call asks for
CREATE FUNCTION authz_int.users_only(p_what text) RETURNS void
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE v_type text; v_id text;
BEGIN
  SELECT p.principal_type, p.principal_id INTO v_type, v_id FROM authz.principal() p;
  IF v_type <> 'user' THEN
    RAISE EXCEPTION '% is for users, not services (% % is signed in)', p_what, v_type, v_id
      USING ERRCODE = 'insufficient_privilege', HINT = 'rowstile help AZ715';
  END IF;
END $f$;
-- the role that called (inside SECURITY DEFINER functions current_user is the owner)
CREATE FUNCTION authz_int.caller_role() RETURNS text
LANGUAGE sql STABLE AS $f$
  SELECT CASE WHEN current_setting('role') = 'none' THEN session_user::text ELSE current_setting('role') END $f$;
-- The caller is an administrator, not the app: a superuser, BYPASSRLS, or the policy's owner (or a member of it)
CREATE FUNCTION authz_int.caller_is_admin() RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
  SELECT coalesce((SELECT r.rolsuper OR r.rolbypassrls OR pg_has_role(r.oid, n.nspowner, 'MEMBER')
                   FROM pg_roles r, pg_namespace n
                   WHERE r.rolname = authz_int.caller_role() AND n.nspname = 'authz_int'), false) $f$;
-- one row in the audit trail
CREATE FUNCTION authz_int.audit(p_action text, p_object_type text, p_object_id text, p_relation text,
  p_subject_type text, p_subject_id text, p_subject_relation text, p_detail jsonb) RETURNS void
LANGUAGE sql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
  INSERT INTO authz.audit (db_role, user_id, acting_user, action, object_type, object_id, relation,
                           subject_type, subject_id, subject_relation, detail, reason)
  VALUES (authz_int.caller_role(), authz_int.actor(),
          nullif(current_setting('authz.acting_user', true), ''), p_action, p_object_type, p_object_id, p_relation,
          p_subject_type, p_subject_id, p_subject_relation, p_detail,
          nullif(current_setting('authz_ctx.reason', true), '')) $f$;

-- The change feed: objects whose access may have changed. Consumers poll authz.changes_since(pos).
-- NOTIFY on channel authz_changes only with INSERT INTO authz.settings VALUES ('notify_changes', 'on'):
-- Postgres commits notifying transactions one at a time, so it would queue every write.
CREATE FUNCTION authz_int.changed(p_type text, p_ids text[], p_cause text) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE v_pos bigint;
BEGIN
  IF coalesce(cardinality(p_ids), 0) = 0 THEN RETURN; END IF;
  INSERT INTO authz.changes (object_type, object_ids, cause) VALUES (p_type, p_ids, p_cause) RETURNING pos INTO v_pos;
  IF (SELECT s.value FROM authz.settings s WHERE s.key = 'notify_changes') = 'on' THEN
    PERFORM pg_notify('authz_changes', v_pos::text);
  END IF;
END $f$;
-- Read the feed from a position: SELECT * FROM authz.changes_since(0)  (administrators, sync jobs).
-- A reader behind what authz.trim_changes() removed gets an error: it must read everything again.
CREATE OR REPLACE FUNCTION authz.changes_since(p_pos bigint, p_limit int DEFAULT 1000) RETURNS SETOF authz.changes
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE v_to bigint := (SELECT s.value::bigint FROM authz.settings s WHERE s.key = 'changes_trimmed_to');
BEGIN
  IF p_pos < v_to THEN
    RAISE EXCEPTION 'the change feed up to position % was trimmed: read everything again, then follow from there', v_to
      USING ERRCODE = 'object_not_in_prerequisite_state', HINT = 'rowstile help AZ712';
  END IF;
  RETURN QUERY SELECT * FROM authz.changes WHERE pos > p_pos ORDER BY pos LIMIT p_limit;
END $f$;

-- Retention (both grow forever otherwise); schedule these, with pg_cron or the app's jobs.
-- The feed: entries older than p_keep, by default the setting changes_keep, else 7 days.
CREATE OR REPLACE FUNCTION authz.trim_changes(p_keep interval DEFAULT NULL) RETURNS bigint
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE
  v_keep interval := coalesce(p_keep, (SELECT s.value::interval FROM authz.settings s WHERE s.key = 'changes_keep'),
                              interval '7 days');
  v_to bigint; n bigint;
BEGIN
  SELECT max(c.pos) INTO v_to FROM authz.changes c WHERE c.at < now() - v_keep;
  IF v_to IS NULL THEN RETURN 0; END IF;
  DELETE FROM authz.changes c WHERE c.pos <= v_to;
  GET DIAGNOSTICS n = ROW_COUNT;
  INSERT INTO authz.settings VALUES ('changes_trimmed_to', v_to::text)
    ON CONFLICT (key) DO UPDATE SET value = greatest(authz.settings.value::bigint, v_to)::text;
  RETURN n;
END $f$;
-- The audit trail: entries older than p_keep (no default: how long to keep it is a compliance
-- decision). The trim itself is recorded in the audit trail.
CREATE OR REPLACE FUNCTION authz.trim_audit(p_keep interval) RETURNS bigint
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE v_before timestamptz; n bigint;
BEGIN
  IF p_keep IS NULL OR p_keep < interval '0' THEN
    RAISE EXCEPTION 'say how long to keep the audit trail, e.g. authz.trim_audit(interval ''2 years'')' USING ERRCODE = 'invalid_parameter_value', HINT = 'rowstile help AZ710';
  END IF;
  v_before := now() - p_keep;
  -- the one way past the trigger is DDL, as the owner, here: nothing a session can set lets a DELETE through
  -- (ALTER TABLE takes an exclusive lock on the trail until the transaction ends); it is on again as it was, in
  -- every replication role
  ALTER TABLE authz.audit DISABLE TRIGGER authz_audit_append_only;
  DELETE FROM authz.audit a WHERE a.at < v_before;
  GET DIAGNOSTICS n = ROW_COUNT;
  ALTER TABLE authz.audit ENABLE ALWAYS TRIGGER authz_audit_append_only;
  INSERT INTO authz.audit (db_role, user_id, action, detail)
  VALUES (authz_int.caller_role(), authz_int.actor(), 'trim_audit',
          jsonb_build_object('before', v_before, 'rows', n));
  RETURN n;
END $f$;

-- The audit trail only grows, except through authz.trim_audit(). Its triggers fire in every replication role
-- (ENABLE ALWAYS): session_replication_role = replica, which turns ordinary triggers off, leaves them on. A
-- subscription's worker applies its publisher's rows in that role, and the trims made there with them: a process
-- Postgres lists as one (pg_stat_subscription), which no session can make itself
CREATE FUNCTION authz_int.audit_is_append_only() RETURNS trigger
LANGUAGE plpgsql SET search_path = pg_catalog, pg_temp AS $f$
BEGIN
  IF EXISTS (SELECT 1 FROM pg_catalog.pg_stat_subscription s WHERE s.pid = pg_catalog.pg_backend_pid()) THEN
    IF TG_OP = 'UPDATE' THEN
      RETURN NEW;
    END IF;
    RETURN OLD;
  END IF;
  RAISE EXCEPTION 'the audit trail cannot be changed' USING ERRCODE = 'insufficient_privilege', HINT = 'rowstile help AZ711';
END $f$;
CREATE TRIGGER authz_audit_append_only BEFORE UPDATE OR DELETE ON authz.audit
  FOR EACH ROW EXECUTE FUNCTION authz_int.audit_is_append_only();
ALTER TABLE authz.audit ENABLE ALWAYS TRIGGER authz_audit_append_only;
CREATE TRIGGER authz_audit_no_truncate BEFORE TRUNCATE ON authz.audit
  FOR EACH STATEMENT EXECUTE FUNCTION authz_int.audit_is_append_only();
ALTER TABLE authz.audit ENABLE ALWAYS TRIGGER authz_audit_no_truncate;

-- shares and role assignments
CREATE FUNCTION authz_int.on_grant() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE r authz.shares;
BEGIN
  r := CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
  PERFORM authz_int.audit(CASE TG_OP WHEN 'INSERT' THEN 'share' WHEN 'DELETE' THEN 'unshare' ELSE 'share_changed' END,
    r.object_type, r.object_id, r.relation, r.subject_type,
    CASE WHEN r.subject_type = 'link' THEN '(link)' ELSE r.subject_id END, r.subject_relation,
    jsonb_strip_nulls(jsonb_build_object('expires_at', r.expires_at, 'starts_at', r.starts_at, 'caveat', r.caveat,
                                         'created_by', r.created_by)));
  PERFORM authz_int.changed(r.object_type, ARRAY[r.object_id], 'share');
  IF TG_OP = 'UPDATE' AND OLD.object_id <> NEW.object_id THEN
    PERFORM authz_int.changed(OLD.object_type, ARRAY[OLD.object_id], 'share');
  END IF;
  RETURN NULL;
END $f$;
CREATE TRIGGER authz_grant_audit AFTER INSERT OR UPDATE OR DELETE ON authz.shares
  FOR EACH ROW EXECUTE FUNCTION authz_int.on_grant();
CREATE FUNCTION authz_int.on_role() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
BEGIN
  IF TG_TABLE_NAME = 'roles' THEN
    PERFORM authz_int.audit(lower(TG_OP) || '_role', CASE WHEN TG_OP = 'DELETE' THEN OLD.owner_type ELSE NEW.owner_type END,
      CASE WHEN TG_OP = 'DELETE' THEN OLD.owner_id ELSE NEW.owner_id END, NULL, NULL, NULL, NULL,
      to_jsonb(CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END));
  ELSE
    PERFORM authz_int.audit(CASE TG_OP WHEN 'DELETE' THEN 'role_permission_removed' ELSE 'role_permission_added' END,
      NULL, NULL, 'role:' || CASE WHEN TG_OP = 'DELETE' THEN OLD.role_id ELSE NEW.role_id END, NULL, NULL, NULL,
      jsonb_build_object('permission', CASE WHEN TG_OP = 'DELETE' THEN OLD.permission ELSE NEW.permission END));
  END IF;
  RETURN NULL;
END $f$;
CREATE TRIGGER authz_role_audit AFTER INSERT OR UPDATE OR DELETE ON authz.roles
  FOR EACH ROW EXECUTE FUNCTION authz_int.on_role();
CREATE TRIGGER authz_role_perm_audit AFTER INSERT OR DELETE ON authz.role_permissions
  FOR EACH ROW EXECUTE FUNCTION authz_int.on_role();

DO $r$ BEGIN PERFORM set_config('authz_ctx.reason', 'applying the policy: the row was deleted', true); END $r$;

-- Shares stored with ids that aren't canonical ('007', an uppercase uuid: written directly before every
-- write went through authz_int.canon) are made canonical, since the sweep below and the triggers compare
-- text; one that then repeats a share already stored goes, the first made staying
CREATE TEMP TABLE authz_uncanonical ON COMMIT DROP AS
  SELECT g.ctid AS row, authz_int.canon(g.object_type, g.object_id) AS object_id,
         authz_int.canon(g.subject_type, g.subject_id) AS subject_id
  FROM authz.shares g
  WHERE g.object_id IS DISTINCT FROM authz_int.canon(g.object_type, g.object_id)
     OR g.subject_id IS DISTINCT FROM authz_int.canon(g.subject_type, g.subject_id);
DELETE FROM authz.shares g USING authz_uncanonical u
WHERE g.ctid = u.row AND EXISTS (
  SELECT 1 FROM authz.shares c WHERE c.object_type = g.object_type AND c.object_id = u.object_id AND c.relation = g.relation
    AND c.subject_type = g.subject_type AND c.subject_id = u.subject_id AND c.subject_relation = g.subject_relation);
DELETE FROM authz.shares g USING (
  SELECT u.row, row_number() OVER (PARTITION BY s.object_type, u.object_id, s.relation, s.subject_type, u.subject_id,
                                   s.subject_relation ORDER BY s.created_at, u.row) AS n
  FROM authz_uncanonical u JOIN authz.shares s ON s.ctid = u.row) d
WHERE g.ctid = d.row AND d.n > 1;
UPDATE authz.shares g SET object_id = u.object_id, subject_id = u.subject_id FROM authz_uncanonical u WHERE g.ctid = u.row;
DROP TABLE authz_uncanonical;

-- Shares on rows that no longer exist (deleted while no trigger watched them) are dropped
DELETE FROM authz.shares g WHERE g.object_type = 'user' AND NOT EXISTS (SELECT 1 FROM "cx"."users" x WHERE x."id"::text = g.object_id);
DELETE FROM authz.shares g WHERE g.subject_type = 'user' AND g.subject_id <> '*' AND NOT EXISTS (SELECT 1 FROM "cx"."users" x WHERE x."id"::text = g.subject_id);
DELETE FROM authz.shares g WHERE g.object_type = 'bot' AND NOT EXISTS (SELECT 1 FROM "cx"."bots" x WHERE x."id"::text = g.object_id);
DELETE FROM authz.shares g WHERE g.subject_type = 'bot' AND g.subject_id <> '*' AND NOT EXISTS (SELECT 1 FROM "cx"."bots" x WHERE x."id"::text = g.subject_id);
DELETE FROM authz.shares g WHERE g.object_type = 'org' AND NOT EXISTS (SELECT 1 FROM "cx"."orgs" x WHERE x."id"::text = g.object_id);
DELETE FROM authz.shares g WHERE g.subject_type = 'org' AND g.subject_id <> '*' AND NOT EXISTS (SELECT 1 FROM "cx"."orgs" x WHERE x."id"::text = g.subject_id);
DELETE FROM authz.shares g WHERE g.object_type = 'team' AND NOT EXISTS (SELECT 1 FROM "cx"."teams" x WHERE ROW(x."org_id"::bigint, x."slug"::text)::text = g.object_id);
DELETE FROM authz.shares g WHERE g.subject_type = 'team' AND g.subject_id <> '*' AND NOT EXISTS (SELECT 1 FROM "cx"."teams" x WHERE ROW(x."org_id"::bigint, x."slug"::text)::text = g.subject_id);
DELETE FROM authz.shares g WHERE g.object_type = 'project' AND NOT EXISTS (SELECT 1 FROM "cx"."projects" x WHERE ROW(x."org_id"::bigint, x."id"::bigint)::text = g.object_id);
DELETE FROM authz.shares g WHERE g.subject_type = 'project' AND g.subject_id <> '*' AND NOT EXISTS (SELECT 1 FROM "cx"."projects" x WHERE ROW(x."org_id"::bigint, x."id"::bigint)::text = g.subject_id);
DELETE FROM authz.shares g WHERE g.object_type = 'folder' AND NOT EXISTS (SELECT 1 FROM "cx"."folders" x WHERE ROW(x."org_id"::bigint, x."id"::bigint)::text = g.object_id);
DELETE FROM authz.shares g WHERE g.subject_type = 'folder' AND g.subject_id <> '*' AND NOT EXISTS (SELECT 1 FROM "cx"."folders" x WHERE ROW(x."org_id"::bigint, x."id"::bigint)::text = g.subject_id);
DELETE FROM authz.shares g WHERE g.object_type = 'file' AND NOT EXISTS (SELECT 1 FROM "cx"."files" x WHERE ROW(x."org_id"::bigint, x."id"::bigint)::text = g.object_id);
DELETE FROM authz.shares g WHERE g.subject_type = 'file' AND g.subject_id <> '*' AND NOT EXISTS (SELECT 1 FROM "cx"."files" x WHERE ROW(x."org_id"::bigint, x."id"::bigint)::text = g.subject_id);
-- ...and so are the API keys of principals that no longer exist
DELETE FROM authz.api_keys k WHERE k.principal_type = 'user' AND NOT EXISTS (SELECT 1 FROM "cx"."users" x WHERE x."id"::text = k.user_id);
DELETE FROM authz.api_keys k WHERE k.principal_type = 'bot' AND NOT EXISTS (SELECT 1 FROM "cx"."bots" x WHERE x."id"::text = k.user_id);
-- ...and pending access requests whose requester no longer exists are cancelled (not those whose object
-- doesn't: a request for a missing object is allowed, so that asking doesn't tell which hidden ones exist)
UPDATE authz.requests r SET status = 'cancelled', decided_at = now(), note = 'its requester is gone' WHERE r.status = 'pending' AND NOT EXISTS (SELECT 1 FROM "cx"."users" x WHERE x."id"::text = r.requester);

DO $r$ BEGIN PERFORM set_config('authz_ctx.reason', '', true); END $r$;

-- 'shared if {...}' conditions (they run as the policy's owner, like permissions)
CREATE FUNCTION authz_int.share_if(p_key text, p_object_id text, p_subject_type text, p_subject_id text,
  p_subject_relation text) RETURNS boolean
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
BEGIN
  CASE p_key
    WHEN NULL THEN NULL;
    ELSE RETURN true;
  END CASE;
END $f$;

-- `roles : ... from rel`: a role counts on an object only if what rel links the object to owns it
CREATE FUNCTION authz_int.role_owned(p_type text, p_id text, p_owner_type text, p_owner_id text) RETURNS boolean
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
BEGIN
  CASE p_type
    WHEN NULL THEN NULL;
    ELSE RETURN true;
  END CASE;
END $f$;
-- the type that owns the custom roles of an object type, when the policy says (from rel)
CREATE FUNCTION authz_int.role_owner_type(p_object_type text) RETURNS text
LANGUAGE plpgsql IMMUTABLE SET search_path = pg_catalog, pg_temp AS $f$
BEGIN
  CASE p_object_type
    WHEN NULL THEN NULL;
    ELSE RETURN NULL;
  END CASE;
END $f$;
-- relations ('role:<id>') of the custom roles that include a permission
CREATE FUNCTION authz_int.role_relations(p_type text, p_perm text) RETURNS text[]
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
  SELECT coalesce(array_agg('role:' || r.id), '{}') FROM authz.roles r
  JOIN authz.role_permissions p ON p.role_id = r.id
  WHERE r.object_type = p_type AND p.permission = p_perm $f$;
-- deleting a role removes its assignments
CREATE FUNCTION authz_int.role_gone() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
BEGIN
  DELETE FROM authz.shares WHERE relation IN (SELECT 'role:' || o.id FROM old_rows o);
  RETURN NULL;
END $f$;
CREATE TRIGGER authz_role_gone AFTER DELETE ON authz.roles
  REFERENCING OLD TABLE AS old_rows FOR EACH STATEMENT EXECUTE FUNCTION authz_int.role_gone();

-- a share, a key or a request naming a row marks it (a new version of its mark, which a transaction that can't
-- see it and then deletes the row, or changes its id, writes too: forget_marks)
CREATE FUNCTION authz_int.mark_row(p_type text, p_id text) RETURNS void
LANGUAGE sql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
  INSERT INTO authz_int.row_marks AS m (type, id) VALUES (p_type, p_id)
  ON CONFLICT (type, id) DO UPDATE SET n = m.n + 1 $f$;
-- rows that are gone, or whose id changed: their marks go too. In a transaction whose snapshot may be older than a
-- share, key or request naming one of them (not READ COMMITTED), the marks are written first: if one was made since,
-- that fails to serialize (40001), rather than leave what the deletes after can't see
CREATE FUNCTION authz_int.forget_marks(p_type text, p_ids text[]) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
BEGIN
  IF pg_catalog.current_setting('transaction_isolation') <> 'read committed' THEN
    INSERT INTO authz_int.row_marks AS m (type, id) SELECT DISTINCT p_type, x FROM unnest(p_ids) x
    ON CONFLICT (type, id) DO UPDATE SET n = m.n + 1;
  END IF;
  DELETE FROM authz_int.row_marks WHERE type = p_type AND id = ANY (p_ids);
END $f$;
-- whether a row is there, locked (FOR KEY SHARE) until the transaction ends, as authz.share locks what it shares
CREATE FUNCTION authz_int.hold(p_type text, p_id text) RETURNS boolean
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE v_tbl text; v_find text; v_found boolean;
BEGIN
  SELECT t.tbl, t.find INTO v_tbl, v_find FROM authz_int.types t WHERE t.name = p_type;
  -- (the key's type by a subquery, never a variable: pg_input_is_valid takes a variable's first value for every
  -- later call from the same line, so a uuid key checked after a bigint one would be invalid)
  IF v_tbl IS NULL OR NOT pg_catalog.pg_input_is_valid(p_id, (SELECT t.keytype FROM authz_int.types t WHERE t.name = p_type)) THEN
    RETURN false;
  END IF;
  EXECUTE format('SELECT EXISTS (SELECT 1 FROM %s x WHERE %s FOR KEY SHARE)', v_tbl, v_find) INTO v_found USING p_id;
  RETURN v_found;
END $f$;

-- user: each row with every ancestor it inherits from, through manager
CREATE TABLE authz_int."user__manager__tree" (descendant bigint NOT NULL, ancestor bigint NOT NULL,
  PRIMARY KEY (descendant, ancestor));
CREATE INDEX ON authz_int."user__manager__tree" (ancestor);
INSERT INTO authz_int.locks VALUES ('user', 0) ON CONFLICT DO NOTHING;
-- kept from the last apply if its definition is the same: its rows are current
DO $k$ BEGIN
  IF to_regclass('authz_keep."user__manager__tree"') IS NOT NULL THEN
    DROP TABLE authz_int."user__manager__tree";
    ALTER TABLE authz_keep."user__manager__tree" SET SCHEMA authz_int;
    INSERT INTO pg_temp.authz_kept VALUES ('user__manager__tree') ON CONFLICT DO NOTHING;
  END IF;
END $k$;

-- every parent link, from every source
CREATE VIEW authz_int."user__manager__tree_links" AS
  SELECT 0 AS _link, r."id" AS _child, r."manager_id" AS _parent FROM "cx"."users" r WHERE r."manager_id" IS NOT NULL;

-- walk up from the given rows; a link is followed only if its condition holds on
-- the child, and the parent exists and passes its type's where
CREATE FUNCTION authz_int."user__manager__tree_compute"(p_ids bigint[]) RETURNS TABLE (o_descendant bigint, o_ancestor bigint)
LANGUAGE sql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
  WITH RECURSIVE up(_d, _a) AS (
    SELECT x."id", x."id" FROM "cx"."users" x WHERE x."id" = ANY (p_ids)
    UNION
    SELECT up._d, e._parent
    FROM up
    -- one index lookup per step: joined plainly, a small table gets a full scan at every step
    -- (OFFSET 0 keeps the planner from turning this into a hash join)
    CROSS JOIN LATERAL (SELECT c.* FROM "cx"."users" c WHERE c."id" = up._a OFFSET 0) c
    CROSS JOIN LATERAL (
      (SELECT x.* FROM (SELECT 0 AS _link, r."id" AS _child, r."manager_id" AS _parent FROM "cx"."users" r WHERE r."manager_id" IS NOT NULL) x WHERE x._child = up._a OFFSET 0)) e
    WHERE (e._link = 0)
      AND EXISTS (SELECT 1 FROM "cx"."users" p WHERE p."id" = e._parent))
  SELECT _d, _a FROM up
$f$;

-- what decides inheritance must be IMMUTABLE
DO $imm$
DECLARE d record;
BEGIN

  FOR d IN SELECT DISTINCT p.oid::regprocedure AS fn
           FROM pg_depend dep
           JOIN pg_rewrite w ON w.oid = dep.objid AND dep.classid = 'pg_rewrite'::regclass
           JOIN pg_proc p ON p.oid = dep.refobjid AND dep.refclassid = 'pg_proc'::regclass
           WHERE w.ev_class IN ('authz_int."user__manager__tree_links"'::regclass) AND p.provolatile <> 'i' LOOP
    RAISE EXCEPTION 'line 5: a condition used for inheritance calls %, which is not IMMUTABLE; read tables with a subquery instead, so changes to them are tracked [AZ603]', d.fn;
  END LOOP;
END $imm$;

-- after a change to the links of p_ids alone (nothing inserted, deleted or renumbered), everything
-- below them (p_below, which includes them) keeps its stored rows among itself, and only rows to the
-- ancestors of p_ids, before or after, can change: to those, each row below now reaches whatever the
-- stored rows of the links leaving the part below lead to. A move of a folder with thousands below it
-- then rewrites (below it) x (its old and new ancestors) rows instead of recomputing every one. That
-- holds only if no link of p_ids, before or after, leads back into the part below them (checked here;
-- false means nothing was done and the caller recomputes). Plans are made for each call's arrays:
-- one made for a few rows would be ruinous for a big move
CREATE FUNCTION authz_int."user__manager__tree_shift"(p_ids bigint[], p_below bigint[]) RETURNS boolean
LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT SET plan_cache_mode = force_custom_plan AS $f$
DECLARE touched bigint[];
BEGIN
  IF EXISTS (SELECT 1 FROM authz_int."user__manager__tree" t JOIN unnest(p_below) b(id) ON b.id = t.ancestor
             WHERE t.descendant = ANY (p_ids) AND t.ancestor <> t.descendant) THEN
    RETURN false;
  END IF;
  IF EXISTS (SELECT 1 FROM unnest(p_ids) b(_y) JOIN "cx"."users" c ON c."id" = b._y
             CROSS JOIN LATERAL (
               (SELECT x.* FROM (SELECT 0 AS _link, r."id" AS _child, r."manager_id" AS _parent FROM "cx"."users" r WHERE r."manager_id" IS NOT NULL) x WHERE x._child = b._y OFFSET 0)) e
             WHERE (e._link = 0) AND e._parent = ANY (p_below)) THEN
    RETURN false;
  END IF;
  -- the ancestors of p_ids before (stored) and after (through their links now): no others change
  touched := ARRAY(
    SELECT t.ancestor FROM authz_int."user__manager__tree" t WHERE t.descendant = ANY (p_ids) AND t.ancestor <> t.descendant
    UNION
    SELECT u.ancestor FROM unnest(p_ids) b(_y) JOIN "cx"."users" c ON c."id" = b._y
    CROSS JOIN LATERAL (
      (SELECT x.* FROM (SELECT 0 AS _link, r."id" AS _child, r."manager_id" AS _parent FROM "cx"."users" r WHERE r."manager_id" IS NOT NULL) x WHERE x._child = b._y OFFSET 0)) e
    JOIN authz_int."user__manager__tree" u ON u.descendant = e._parent
    WHERE (e._link = 0));
  WITH below AS MATERIALIZED (SELECT x AS _y FROM unnest(p_below) x),
  -- links from the part below to outside it, as they are now
  exits AS MATERIALIZED (
    SELECT e._child AS y, e._parent AS p
    FROM below JOIN "cx"."users" c ON c."id" = below._y
    CROSS JOIN LATERAL (
      (SELECT x.* FROM (SELECT 0 AS _link, r."id" AS _child, r."manager_id" AS _parent FROM "cx"."users" r WHERE r."manager_id" IS NOT NULL) x WHERE x._child = below._y OFFSET 0)) e
    WHERE (e._link = 0)),
  -- each row below: the touched ancestors it now reaches, through the exits it reaches
  fresh AS MATERIALIZED (
    SELECT DISTINCT d.descendant AS d, u.ancestor AS a
    FROM exits
    JOIN authz_int."user__manager__tree" u ON u.descendant = exits.p AND u.ancestor = ANY (touched)
    JOIN authz_int."user__manager__tree" d ON d.ancestor = exits.y
    WHERE NOT EXISTS (SELECT 1 FROM below b WHERE b._y = exits.p)),
  stale AS (
    DELETE FROM authz_int."user__manager__tree" t
    WHERE t.ancestor = ANY (touched) AND t.descendant IN (SELECT _y FROM below)
      AND NOT EXISTS (SELECT 1 FROM fresh o WHERE o.d = t.descendant AND o.a = t.ancestor))
  INSERT INTO authz_int."user__manager__tree" (descendant, ancestor) SELECT d, a FROM fresh ON CONFLICT DO NOTHING;
  RETURN true;
END $f$;

-- recompute the given rows and everything linked below them; p_shift: only their own links changed
CREATE FUNCTION authz_int."user__manager__tree_refresh"(p_ids bigint[], p_shift boolean DEFAULT false) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $f$
DECLARE affected bigint[];
BEGIN
  IF coalesce(cardinality(p_ids), 0) = 0 THEN RETURN; END IF;
  UPDATE authz_int.locks SET n = n + 1 WHERE type IN ('user');
  WITH RECURSIVE down(id) AS (
    SELECT x FROM unnest(p_ids) AS x WHERE x IS NOT NULL
    UNION
    SELECT e._child FROM down CROSS JOIN LATERAL (
      (SELECT x.* FROM (SELECT 0 AS _link, r."id" AS _child, r."manager_id" AS _parent FROM "cx"."users" r WHERE r."manager_id" IS NOT NULL) x WHERE x._parent = down.id OFFSET 0)) e)
  SELECT array_agg(id) INTO affected FROM down;
  IF NOT (p_shift AND authz_int."user__manager__tree_shift"(p_ids, affected)) THEN
    DELETE FROM authz_int."user__manager__tree" WHERE descendant = ANY (affected);
    INSERT INTO authz_int."user__manager__tree" (descendant, ancestor)
    SELECT o_descendant, o_ancestor FROM authz_int."user__manager__tree_compute"(affected);
  END IF;
  PERFORM authz_int.changed('user', affected::text[], 'inheritance');
END $f$;

-- recompute everything (backfill, TRUNCATE), 10000 rows at a time
CREATE FUNCTION authz_int."user__manager__tree_rebuild"() RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $f$
DECLARE batch bigint[];
BEGIN
  UPDATE authz_int.locks SET n = n + 1 WHERE type IN ('user');
  DELETE FROM authz_int."user__manager__tree";
  FOR batch IN SELECT array_agg(k.k) FROM (SELECT "id" AS k, row_number() OVER () AS n FROM "cx"."users") k GROUP BY (k.n - 1) / 10000 LOOP
    INSERT INTO authz_int."user__manager__tree" (descendant, ancestor)
    SELECT o_descendant, o_ancestor FROM authz_int."user__manager__tree_compute"(batch);
  END LOOP;
END $f$;
CREATE FUNCTION authz_int."user__manager__tree_on_truncate"() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $f$
BEGIN PERFORM authz_int."user__manager__tree_rebuild"(); RETURN NULL; END $f$;

-- what a rebuild would give against what is stored, 10000 rows at a time; then nothing stored for a row
-- that is gone
CREATE FUNCTION authz_int."user__manager__tree_verify"() RETURNS boolean
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
DECLARE batch bigint[];
BEGIN
  FOR batch IN SELECT array_agg(k.k) FROM (SELECT "id" AS k, row_number() OVER () AS n FROM "cx"."users") k GROUP BY (k.n - 1) / 10000 LOOP
    IF EXISTS (WITH fresh AS MATERIALIZED (SELECT o_descendant AS d, o_ancestor AS a FROM authz_int."user__manager__tree_compute"(batch)),
                    stored AS MATERIALIZED (SELECT descendant AS d, ancestor AS a FROM authz_int."user__manager__tree"
                                            WHERE descendant = ANY (batch))
               (SELECT d, a FROM fresh EXCEPT SELECT d, a FROM stored)
               UNION ALL
               (SELECT d, a FROM stored EXCEPT SELECT d, a FROM fresh)) THEN
      RETURN false;
    END IF;
  END LOOP;
  IF EXISTS (SELECT 1 FROM authz_int."user__manager__tree" s
             WHERE NOT EXISTS (SELECT 1 FROM "cx"."users" x WHERE x."id" = s.descendant)) THEN
    RETURN false;
  END IF;
  RETURN true;
END $f$;

-- the tree's own columns may not loop (links through tables may: they add nothing)
CREATE VIEW authz_int."user__manager__tree_parents" AS
  SELECT r."id" AS _child, r."manager_id" AS _parent FROM "cx"."users" r WHERE r."manager_id" IS NOT NULL;
CREATE FUNCTION authz_int."user__manager__tree_check_loops"(p_ids bigint[]) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $f$
DECLARE bad text;
BEGIN
  WITH RECURSIVE up(start, id) AS (
    SELECT e._child, e._parent FROM authz_int."user__manager__tree_parents" e WHERE e._child = ANY (p_ids)
    UNION
    SELECT up.start, e._parent FROM up CROSS JOIN LATERAL (
      (SELECT x.* FROM (SELECT r."id" AS _child, r."manager_id" AS _parent FROM "cx"."users" r WHERE r."manager_id" IS NOT NULL) x WHERE x._child = up.id OFFSET 0)) e)
  SELECT start::text INTO bad FROM up WHERE id = start LIMIT 1;
  IF bad IS NOT NULL THEN
    RAISE EXCEPTION 'user % cannot be moved inside itself', bad USING ERRCODE = 'check_violation', HINT = 'rowstile help AZ713';
  END IF;
END $f$;

-- rows inserted, deleted, moved, or whose id or conditions change
CREATE FUNCTION authz_int."user__manager__tree_on_rows"() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $f$
DECLARE ids bigint[]; shift boolean := false;
BEGIN
  IF TG_OP = 'INSERT' THEN
    ids := ARRAY(SELECT n."id" FROM new_rows n);
  ELSIF TG_OP = 'UPDATE' THEN
    -- rows whose id changed: the old id disappears and the new one appears
    ids := ARRAY(
      SELECT o."id" FROM old_rows o WHERE NOT EXISTS (SELECT 1 FROM new_rows n WHERE n."id" = o."id")
      UNION SELECT n."id" FROM new_rows n WHERE NOT EXISTS (SELECT 1 FROM old_rows o WHERE o."id" = n."id"));
    shift := cardinality(ids) = 0;
    ids := ARRAY(
      SELECT n."id" FROM new_rows n JOIN old_rows o ON o."id" = n."id"
      WHERE n."manager_id" IS DISTINCT FROM o."manager_id"
      UNION SELECT unnest(ids));
  ELSE
    ids := ARRAY(SELECT o."id" FROM old_rows o);
  END IF;
  IF cardinality(ids) > 0 THEN
    UPDATE authz_int.locks SET n = n + 1 WHERE type IN ('user');
  IF TG_OP <> 'DELETE' THEN PERFORM authz_int."user__manager__tree_check_loops"(ids); END IF;
    PERFORM authz_int."user__manager__tree_refresh"(ids, shift);
  END IF;
  RETURN NULL;
END $f$;
CREATE TRIGGER "authz_user__manager__tree_ins" AFTER INSERT ON "cx"."users"
  REFERENCING NEW TABLE AS new_rows FOR EACH STATEMENT EXECUTE FUNCTION authz_int."user__manager__tree_on_rows"();
CREATE TRIGGER "authz_user__manager__tree_upd" AFTER UPDATE ON "cx"."users"
  REFERENCING OLD TABLE AS old_rows NEW TABLE AS new_rows FOR EACH STATEMENT EXECUTE FUNCTION authz_int."user__manager__tree_on_rows"();
CREATE TRIGGER "authz_user__manager__tree_del" AFTER DELETE ON "cx"."users"
  REFERENCING OLD TABLE AS old_rows FOR EACH STATEMENT EXECUTE FUNCTION authz_int."user__manager__tree_on_rows"();
CREATE TRIGGER "authz_user__manager__tree_trunc" AFTER TRUNCATE ON "cx"."users"
  FOR EACH STATEMENT EXECUTE FUNCTION authz_int."user__manager__tree_on_truncate"();

-- backfill from the rows already there (unless the tree was kept)
DO $b$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_temp.authz_kept WHERE name = 'user__manager__tree') THEN
    PERFORM authz_int."user__manager__tree_rebuild"();
  END IF;
END $b$;

-- folder, project: each node with every ancestor it inherits from, through folder.parent -> folder, folder.parent -> project, project.folder -> folder
CREATE TABLE authz_int."folder_project__folder_parent__tree" (dtype text NOT NULL, did text NOT NULL, atype text NOT NULL, aid text NOT NULL,
  PRIMARY KEY (dtype, did, atype, aid));
CREATE INDEX ON authz_int."folder_project__folder_parent__tree" (atype, aid);

INSERT INTO authz_int.locks SELECT x, 0 FROM unnest(ARRAY['folder', 'project']) x ON CONFLICT DO NOTHING;
-- kept from the last apply if its definition is the same: its rows are current
DO $k$ BEGIN
  IF to_regclass('authz_keep."folder_project__folder_parent__tree"') IS NOT NULL THEN
    DROP TABLE authz_int."folder_project__folder_parent__tree";
    ALTER TABLE authz_keep."folder_project__folder_parent__tree" SET SCHEMA authz_int;
    INSERT INTO pg_temp.authz_kept VALUES ('folder_project__folder_parent__tree') ON CONFLICT DO NOTHING;
  END IF;
END $k$;

-- walk up from the given nodes; a link is followed only if its condition holds on
-- the child, and the parent exists and passes its type's where
CREATE FUNCTION authz_int."folder_project__folder_parent__tree_compute"(p_types text[], p_ids text[])
RETURNS TABLE (o_dtype text, o_did text, o_atype text, o_aid text)
LANGUAGE sql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
  WITH RECURSIVE up(_dt, _d, _at, _a) AS (
    SELECT n.t, n.i, n.t, n.i FROM unnest(p_types, p_ids) AS n(t, i)
    WHERE CASE n.t WHEN 'folder' THEN EXISTS (SELECT 1 FROM "cx"."folders" x WHERE (x."org_id", x."id") = ((((CASE WHEN n.t = 'folder' THEN n.i END)::text)::authz_gen."folder__key")."org_id", (((CASE WHEN n.t = 'folder' THEN n.i END)::text)::authz_gen."folder__key")."id")) WHEN 'project' THEN EXISTS (SELECT 1 FROM "cx"."projects" x WHERE (x."org_id", x."id") = ((((CASE WHEN n.t = 'project' THEN n.i END)::text)::authz_gen."project__key")."org_id", (((CASE WHEN n.t = 'project' THEN n.i END)::text)::authz_gen."project__key")."id")) ELSE false END
    UNION
    SELECT up._dt, up._d, e.pt, e.p
    FROM up CROSS JOIN LATERAL (
      
SELECT 'folder'::text AS pt, ((CASE WHEN r."parent_type" = 'folder' THEN (CASE WHEN (r."org_id", r."parent_id") IS NOT NULL THEN ROW(r."org_id"::bigint, r."parent_id"::bigint)::text END) END))::text AS p FROM "cx"."folders" r WHERE (r."org_id", r."id") = ((((CASE WHEN up._at = 'folder' THEN up._a END)::text)::authz_gen."folder__key")."org_id", (((CASE WHEN up._at = 'folder' THEN up._a END)::text)::authz_gen."folder__key")."id") AND (CASE WHEN r."parent_type" = 'folder' THEN (CASE WHEN (r."org_id", r."parent_id") IS NOT NULL THEN ROW(r."org_id"::bigint, r."parent_id"::bigint)::text END) END) IS NOT NULL AND true AND EXISTS (SELECT 1 FROM "cx"."folders" pp WHERE (pp."org_id", pp."id") = ((((CASE WHEN r."parent_type" = 'folder' THEN (CASE WHEN (r."org_id", r."parent_id") IS NOT NULL THEN ROW(r."org_id"::bigint, r."parent_id"::bigint)::text END) END))::authz_gen."folder__key")."org_id", (((CASE WHEN r."parent_type" = 'folder' THEN (CASE WHEN (r."org_id", r."parent_id") IS NOT NULL THEN ROW(r."org_id"::bigint, r."parent_id"::bigint)::text END) END))::authz_gen."folder__key")."id"))      UNION ALL SELECT 'folder'::text AS pt, ((CASE WHEN (s."org_id", s."parent_id") IS NOT NULL THEN ROW(s."org_id"::bigint, s."parent_id"::bigint)::text END))::text AS p FROM "cx"."folder_links" s WHERE (s."org_id", s."child_id") = ((((CASE WHEN up._at = 'folder' THEN up._a END)::text)::authz_gen."folder__key")."org_id", (((CASE WHEN up._at = 'folder' THEN up._a END)::text)::authz_gen."folder__key")."id") AND (CASE WHEN (s."org_id", s."parent_id") IS NOT NULL THEN ROW(s."org_id"::bigint, s."parent_id"::bigint)::text END) IS NOT NULL AND true AND EXISTS (SELECT 1 FROM "cx"."folders" pp WHERE (pp."org_id", pp."id") = ((((CASE WHEN (s."org_id", s."parent_id") IS NOT NULL THEN ROW(s."org_id"::bigint, s."parent_id"::bigint)::text END))::authz_gen."folder__key")."org_id", (((CASE WHEN (s."org_id", s."parent_id") IS NOT NULL THEN ROW(s."org_id"::bigint, s."parent_id"::bigint)::text END))::authz_gen."folder__key")."id"))      UNION ALL SELECT 'project'::text AS pt, ((CASE WHEN r."parent_type" = 'project' THEN (CASE WHEN (r."org_id", r."parent_id") IS NOT NULL THEN ROW(r."org_id"::bigint, r."parent_id"::bigint)::text END) END))::text AS p FROM "cx"."folders" r WHERE (r."org_id", r."id") = ((((CASE WHEN up._at = 'folder' THEN up._a END)::text)::authz_gen."folder__key")."org_id", (((CASE WHEN up._at = 'folder' THEN up._a END)::text)::authz_gen."folder__key")."id") AND (CASE WHEN r."parent_type" = 'project' THEN (CASE WHEN (r."org_id", r."parent_id") IS NOT NULL THEN ROW(r."org_id"::bigint, r."parent_id"::bigint)::text END) END) IS NOT NULL AND true AND EXISTS (SELECT 1 FROM "cx"."projects" pp WHERE (pp."org_id", pp."id") = ((((CASE WHEN r."parent_type" = 'project' THEN (CASE WHEN (r."org_id", r."parent_id") IS NOT NULL THEN ROW(r."org_id"::bigint, r."parent_id"::bigint)::text END) END))::authz_gen."project__key")."org_id", (((CASE WHEN r."parent_type" = 'project' THEN (CASE WHEN (r."org_id", r."parent_id") IS NOT NULL THEN ROW(r."org_id"::bigint, r."parent_id"::bigint)::text END) END))::authz_gen."project__key")."id"))      UNION ALL SELECT 'folder'::text AS pt, ((CASE WHEN (r."org_id", r."folder_id") IS NOT NULL THEN ROW(r."org_id"::bigint, r."folder_id"::bigint)::text END))::text AS p FROM "cx"."projects" r WHERE (r."org_id", r."id") = ((((CASE WHEN up._at = 'project' THEN up._a END)::text)::authz_gen."project__key")."org_id", (((CASE WHEN up._at = 'project' THEN up._a END)::text)::authz_gen."project__key")."id") AND (CASE WHEN (r."org_id", r."folder_id") IS NOT NULL THEN ROW(r."org_id"::bigint, r."folder_id"::bigint)::text END) IS NOT NULL AND true AND EXISTS (SELECT 1 FROM "cx"."folders" pp WHERE (pp."org_id", pp."id") = ((((CASE WHEN (r."org_id", r."folder_id") IS NOT NULL THEN ROW(r."org_id"::bigint, r."folder_id"::bigint)::text END))::authz_gen."folder__key")."org_id", (((CASE WHEN (r."org_id", r."folder_id") IS NOT NULL THEN ROW(r."org_id"::bigint, r."folder_id"::bigint)::text END))::authz_gen."folder__key")."id"))) e)
  SELECT _dt, _d, _at, _a FROM up
$f$;

-- recompute the given nodes and everything linked below them
CREATE FUNCTION authz_int."folder_project__folder_parent__tree_refresh"(p_types text[], p_ids text[]) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $f$
DECLARE a_t text[]; a_i text[];
BEGIN
  IF coalesce(cardinality(p_ids), 0) = 0 THEN RETURN; END IF;
  UPDATE authz_int.locks SET n = n + 1 WHERE type IN ('folder', 'project');
  WITH RECURSIVE down(_t, _i) AS (
    SELECT x.t, x.i FROM unnest(p_types, p_ids) AS x(t, i) WHERE x.i IS NOT NULL
    UNION
    SELECT e.ct, e.c FROM down CROSS JOIN LATERAL (
      
SELECT 'folder'::text AS ct, ROW(r."org_id"::bigint, r."id"::bigint)::text AS c FROM "cx"."folders" r WHERE (r."org_id", r."parent_id") = ((((CASE WHEN down._t = 'folder' THEN down._i END)::text)::authz_gen."folder__key")."org_id", (((CASE WHEN down._t = 'folder' THEN down._i END)::text)::authz_gen."folder__key")."id") AND r."parent_type" = 'folder'      UNION ALL SELECT 'folder'::text AS ct, (CASE WHEN (s."org_id", s."child_id") IS NOT NULL THEN ROW(s."org_id"::bigint, s."child_id"::bigint)::text END) AS c FROM "cx"."folder_links" s WHERE (s."org_id", s."parent_id") = ((((CASE WHEN down._t = 'folder' THEN down._i END)::text)::authz_gen."folder__key")."org_id", (((CASE WHEN down._t = 'folder' THEN down._i END)::text)::authz_gen."folder__key")."id")      UNION ALL SELECT 'folder'::text AS ct, ROW(r."org_id"::bigint, r."id"::bigint)::text AS c FROM "cx"."folders" r WHERE (r."org_id", r."parent_id") = ((((CASE WHEN down._t = 'project' THEN down._i END)::text)::authz_gen."project__key")."org_id", (((CASE WHEN down._t = 'project' THEN down._i END)::text)::authz_gen."project__key")."id") AND r."parent_type" = 'project'      UNION ALL SELECT 'project'::text AS ct, ROW(r."org_id"::bigint, r."id"::bigint)::text AS c FROM "cx"."projects" r WHERE (r."org_id", r."folder_id") = ((((CASE WHEN down._t = 'folder' THEN down._i END)::text)::authz_gen."folder__key")."org_id", (((CASE WHEN down._t = 'folder' THEN down._i END)::text)::authz_gen."folder__key")."id")) e)
  SELECT array_agg(_t), array_agg(_i) INTO a_t, a_i FROM down;
  DELETE FROM authz_int."folder_project__folder_parent__tree" WHERE (dtype, did) IN (SELECT * FROM unnest(a_t, a_i));
  INSERT INTO authz_int."folder_project__folder_parent__tree" SELECT * FROM authz_int."folder_project__folder_parent__tree_compute"(a_t, a_i);
  PERFORM authz_int.changed(x.t, array_agg(x.i), 'inheritance') FROM unnest(a_t, a_i) x(t, i) GROUP BY x.t;
END $f$;

-- recompute everything (backfill, TRUNCATE), 10000 nodes at a time
CREATE FUNCTION authz_int."folder_project__folder_parent__tree_rebuild"() RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $f$
DECLARE a_t text[]; a_i text[];
BEGIN
  UPDATE authz_int.locks SET n = n + 1 WHERE type IN ('folder', 'project');
  DELETE FROM authz_int."folder_project__folder_parent__tree";
  FOR a_t, a_i IN SELECT array_agg(k.t), array_agg(k.i) FROM (SELECT x.t, x.i, row_number() OVER () AS n FROM (SELECT 'folder'::text AS t, ROW(x."org_id"::bigint, x."id"::bigint)::text AS i FROM "cx"."folders" x UNION ALL SELECT 'project'::text AS t, ROW(x."org_id"::bigint, x."id"::bigint)::text AS i FROM "cx"."projects" x) x) k GROUP BY (k.n - 1) / 10000 LOOP
    INSERT INTO authz_int."folder_project__folder_parent__tree" SELECT * FROM authz_int."folder_project__folder_parent__tree_compute"(a_t, a_i);
  END LOOP;
END $f$;
CREATE FUNCTION authz_int."folder_project__folder_parent__tree_on_truncate"() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $f$
BEGIN PERFORM authz_int."folder_project__folder_parent__tree_rebuild"(); RETURN NULL; END $f$;

-- what a rebuild would give against what is stored, 10000 nodes at a time; then nothing stored for a node
-- that is gone
CREATE FUNCTION authz_int."folder_project__folder_parent__tree_verify"() RETURNS boolean
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
DECLARE a_t text[]; a_i text[];
BEGIN
  FOR a_t, a_i IN SELECT array_agg(k.t), array_agg(k.i) FROM (SELECT x.t, x.i, row_number() OVER () AS n FROM (SELECT 'folder'::text AS t, ROW(x."org_id"::bigint, x."id"::bigint)::text AS i FROM "cx"."folders" x UNION ALL SELECT 'project'::text AS t, ROW(x."org_id"::bigint, x."id"::bigint)::text AS i FROM "cx"."projects" x) x) k GROUP BY (k.n - 1) / 10000 LOOP
    IF EXISTS (WITH fresh AS MATERIALIZED (SELECT * FROM authz_int."folder_project__folder_parent__tree_compute"(a_t, a_i)),
                    stored AS MATERIALIZED (SELECT * FROM authz_int."folder_project__folder_parent__tree"
                                            WHERE (dtype, did) IN (SELECT * FROM unnest(a_t, a_i)))
               (SELECT * FROM fresh EXCEPT SELECT * FROM stored)
               UNION ALL
               (SELECT * FROM stored EXCEPT SELECT * FROM fresh)) THEN
      RETURN false;
    END IF;
  END LOOP;
  IF EXISTS (SELECT 1 FROM (SELECT DISTINCT dtype AS t, did AS i FROM authz_int."folder_project__folder_parent__tree") n
             WHERE NOT CASE n.t WHEN 'folder' THEN EXISTS (SELECT 1 FROM "cx"."folders" x WHERE (x."org_id", x."id") = ((((CASE WHEN n.t = 'folder' THEN n.i END)::text)::authz_gen."folder__key")."org_id", (((CASE WHEN n.t = 'folder' THEN n.i END)::text)::authz_gen."folder__key")."id")) WHEN 'project' THEN EXISTS (SELECT 1 FROM "cx"."projects" x WHERE (x."org_id", x."id") = ((((CASE WHEN n.t = 'project' THEN n.i END)::text)::authz_gen."project__key")."org_id", (((CASE WHEN n.t = 'project' THEN n.i END)::text)::authz_gen."project__key")."id")) ELSE false END) THEN
    RETURN false;
  END IF;
  RETURN true;
END $f$;

-- the types' own columns may not loop (links through tables may: they add nothing)
CREATE FUNCTION authz_int."folder_project__folder_parent__tree_check_loops"(p_types text[], p_ids text[]) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $f$
DECLARE bad text;
BEGIN
  -- a loop means some node reaches itself through at least one link
  WITH RECURSIVE up(_st, _s, _at, _a, _n) AS (
    SELECT x.t, x.i, x.t, x.i, 0 FROM unnest(p_types, p_ids) AS x(t, i)
    UNION
    SELECT up._st, up._s, e.pt, e.p, 1 FROM up CROSS JOIN LATERAL (
      
SELECT 'folder'::text AS pt, ((CASE WHEN r."parent_type" = 'folder' THEN (CASE WHEN (r."org_id", r."parent_id") IS NOT NULL THEN ROW(r."org_id"::bigint, r."parent_id"::bigint)::text END) END))::text AS p FROM "cx"."folders" r WHERE (r."org_id", r."id") = ((((CASE WHEN up._at = 'folder' THEN up._a END)::text)::authz_gen."folder__key")."org_id", (((CASE WHEN up._at = 'folder' THEN up._a END)::text)::authz_gen."folder__key")."id") AND (CASE WHEN r."parent_type" = 'folder' THEN (CASE WHEN (r."org_id", r."parent_id") IS NOT NULL THEN ROW(r."org_id"::bigint, r."parent_id"::bigint)::text END) END) IS NOT NULL      UNION ALL SELECT 'project'::text AS pt, ((CASE WHEN r."parent_type" = 'project' THEN (CASE WHEN (r."org_id", r."parent_id") IS NOT NULL THEN ROW(r."org_id"::bigint, r."parent_id"::bigint)::text END) END))::text AS p FROM "cx"."folders" r WHERE (r."org_id", r."id") = ((((CASE WHEN up._at = 'folder' THEN up._a END)::text)::authz_gen."folder__key")."org_id", (((CASE WHEN up._at = 'folder' THEN up._a END)::text)::authz_gen."folder__key")."id") AND (CASE WHEN r."parent_type" = 'project' THEN (CASE WHEN (r."org_id", r."parent_id") IS NOT NULL THEN ROW(r."org_id"::bigint, r."parent_id"::bigint)::text END) END) IS NOT NULL      UNION ALL SELECT 'folder'::text AS pt, ((CASE WHEN (r."org_id", r."folder_id") IS NOT NULL THEN ROW(r."org_id"::bigint, r."folder_id"::bigint)::text END))::text AS p FROM "cx"."projects" r WHERE (r."org_id", r."id") = ((((CASE WHEN up._at = 'project' THEN up._a END)::text)::authz_gen."project__key")."org_id", (((CASE WHEN up._at = 'project' THEN up._a END)::text)::authz_gen."project__key")."id") AND (CASE WHEN (r."org_id", r."folder_id") IS NOT NULL THEN ROW(r."org_id"::bigint, r."folder_id"::bigint)::text END) IS NOT NULL) e)
  SELECT _st || ' ' || _s INTO bad FROM up WHERE _n = 1 AND (_at, _a) = (_st, _s) LIMIT 1;
  IF bad IS NOT NULL THEN
    RAISE EXCEPTION '% cannot be moved inside itself', bad USING ERRCODE = 'check_violation', HINT = 'rowstile help AZ713';
  END IF;
END $f$;

-- folder rows inserted, deleted, moved, or whose id or conditions change
CREATE FUNCTION authz_int."folder_project__folder_parent__tree_rows_folder"() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $f$
DECLARE ids text[];
BEGIN
  IF TG_OP = 'INSERT' THEN
    ids := ARRAY(SELECT ROW(n."org_id"::bigint, n."id"::bigint)::text FROM new_rows n);
  ELSIF TG_OP = 'UPDATE' THEN
    ids := ARRAY(
      SELECT ROW(n."org_id"::bigint, n."id"::bigint)::text FROM new_rows n JOIN old_rows o ON ROW(o."org_id"::bigint, o."id"::bigint)::text = ROW(n."org_id"::bigint, n."id"::bigint)::text
      WHERE n."org_id" IS DISTINCT FROM o."org_id"
         OR n."parent_id" IS DISTINCT FROM o."parent_id"
         OR n."parent_type" IS DISTINCT FROM o."parent_type"
      UNION SELECT ROW(o."org_id"::bigint, o."id"::bigint)::text FROM old_rows o WHERE NOT EXISTS (SELECT 1 FROM new_rows n WHERE ROW(n."org_id"::bigint, n."id"::bigint)::text = ROW(o."org_id"::bigint, o."id"::bigint)::text)
      UNION SELECT ROW(n."org_id"::bigint, n."id"::bigint)::text FROM new_rows n WHERE NOT EXISTS (SELECT 1 FROM old_rows o WHERE ROW(o."org_id"::bigint, o."id"::bigint)::text = ROW(n."org_id"::bigint, n."id"::bigint)::text));
  ELSE
    ids := ARRAY(SELECT ROW(o."org_id"::bigint, o."id"::bigint)::text FROM old_rows o);
  END IF;
  IF cardinality(ids) > 0 THEN
    UPDATE authz_int.locks SET n = n + 1 WHERE type IN ('folder', 'project');
    IF TG_OP <> 'DELETE' THEN PERFORM authz_int."folder_project__folder_parent__tree_check_loops"(array_fill('folder'::text, ARRAY[cardinality(ids)]), ids); END IF;
    PERFORM authz_int."folder_project__folder_parent__tree_refresh"(array_fill('folder'::text, ARRAY[cardinality(ids)]), ids);
  END IF;
  RETURN NULL;
END $f$;
CREATE TRIGGER "authz_folder_project__folder_parent__tree_rows_folder_ins" AFTER INSERT ON "cx"."folders"
  REFERENCING NEW TABLE AS new_rows FOR EACH STATEMENT EXECUTE FUNCTION authz_int."folder_project__folder_parent__tree_rows_folder"();
CREATE TRIGGER "authz_folder_project__folder_parent__tree_rows_folder_upd" AFTER UPDATE ON "cx"."folders"
  REFERENCING OLD TABLE AS old_rows NEW TABLE AS new_rows FOR EACH STATEMENT EXECUTE FUNCTION authz_int."folder_project__folder_parent__tree_rows_folder"();
CREATE TRIGGER "authz_folder_project__folder_parent__tree_rows_folder_del" AFTER DELETE ON "cx"."folders"
  REFERENCING OLD TABLE AS old_rows FOR EACH STATEMENT EXECUTE FUNCTION authz_int."folder_project__folder_parent__tree_rows_folder"();
CREATE TRIGGER "authz_folder_project__folder_parent__tree_rows_folder_trunc" AFTER TRUNCATE ON "cx"."folders"
  FOR EACH STATEMENT EXECUTE FUNCTION authz_int."folder_project__folder_parent__tree_on_truncate"();

-- project rows inserted, deleted, moved, or whose id or conditions change
CREATE FUNCTION authz_int."folder_project__folder_parent__tree_rows_project"() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $f$
DECLARE ids text[];
BEGIN
  IF TG_OP = 'INSERT' THEN
    ids := ARRAY(SELECT ROW(n."org_id"::bigint, n."id"::bigint)::text FROM new_rows n);
  ELSIF TG_OP = 'UPDATE' THEN
    ids := ARRAY(
      SELECT ROW(n."org_id"::bigint, n."id"::bigint)::text FROM new_rows n JOIN old_rows o ON ROW(o."org_id"::bigint, o."id"::bigint)::text = ROW(n."org_id"::bigint, n."id"::bigint)::text
      WHERE n."org_id" IS DISTINCT FROM o."org_id"
         OR n."folder_id" IS DISTINCT FROM o."folder_id"
      UNION SELECT ROW(o."org_id"::bigint, o."id"::bigint)::text FROM old_rows o WHERE NOT EXISTS (SELECT 1 FROM new_rows n WHERE ROW(n."org_id"::bigint, n."id"::bigint)::text = ROW(o."org_id"::bigint, o."id"::bigint)::text)
      UNION SELECT ROW(n."org_id"::bigint, n."id"::bigint)::text FROM new_rows n WHERE NOT EXISTS (SELECT 1 FROM old_rows o WHERE ROW(o."org_id"::bigint, o."id"::bigint)::text = ROW(n."org_id"::bigint, n."id"::bigint)::text));
  ELSE
    ids := ARRAY(SELECT ROW(o."org_id"::bigint, o."id"::bigint)::text FROM old_rows o);
  END IF;
  IF cardinality(ids) > 0 THEN
    UPDATE authz_int.locks SET n = n + 1 WHERE type IN ('folder', 'project');
    IF TG_OP <> 'DELETE' THEN PERFORM authz_int."folder_project__folder_parent__tree_check_loops"(array_fill('project'::text, ARRAY[cardinality(ids)]), ids); END IF;
    PERFORM authz_int."folder_project__folder_parent__tree_refresh"(array_fill('project'::text, ARRAY[cardinality(ids)]), ids);
  END IF;
  RETURN NULL;
END $f$;
CREATE TRIGGER "authz_folder_project__folder_parent__tree_rows_project_ins" AFTER INSERT ON "cx"."projects"
  REFERENCING NEW TABLE AS new_rows FOR EACH STATEMENT EXECUTE FUNCTION authz_int."folder_project__folder_parent__tree_rows_project"();
CREATE TRIGGER "authz_folder_project__folder_parent__tree_rows_project_upd" AFTER UPDATE ON "cx"."projects"
  REFERENCING OLD TABLE AS old_rows NEW TABLE AS new_rows FOR EACH STATEMENT EXECUTE FUNCTION authz_int."folder_project__folder_parent__tree_rows_project"();
CREATE TRIGGER "authz_folder_project__folder_parent__tree_rows_project_del" AFTER DELETE ON "cx"."projects"
  REFERENCING OLD TABLE AS old_rows FOR EACH STATEMENT EXECUTE FUNCTION authz_int."folder_project__folder_parent__tree_rows_project"();
CREATE TRIGGER "authz_folder_project__folder_parent__tree_rows_project_trunc" AFTER TRUNCATE ON "cx"."projects"
  FOR EACH STATEMENT EXECUTE FUNCTION authz_int."folder_project__folder_parent__tree_on_truncate"();

-- links stored in cx.folder_links
CREATE FUNCTION authz_int."folder_project__folder_parent__tree_on_links1"() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $f$
DECLARE a_t text[]; a_i text[];
BEGIN
  IF TG_OP IN ('INSERT', 'UPDATE') THEN
    SELECT array_agg(t), array_agg(i) INTO a_t, a_i FROM (SELECT 'folder'::text AS t, (CASE WHEN (x."org_id", x."child_id") IS NOT NULL THEN ROW(x."org_id"::bigint, x."child_id"::bigint)::text END) AS i FROM new_rows x) y;
    PERFORM authz_int."folder_project__folder_parent__tree_refresh"(a_t, a_i);
  END IF;
  IF TG_OP IN ('DELETE', 'UPDATE') THEN
    SELECT array_agg(t), array_agg(i) INTO a_t, a_i FROM (SELECT 'folder'::text AS t, (CASE WHEN (x."org_id", x."child_id") IS NOT NULL THEN ROW(x."org_id"::bigint, x."child_id"::bigint)::text END) AS i FROM old_rows x) y;
    PERFORM authz_int."folder_project__folder_parent__tree_refresh"(a_t, a_i);
  END IF;
  RETURN NULL;
END $f$;
CREATE TRIGGER "authz_folder_project__folder_parent__tree_on_links1_ins" AFTER INSERT ON "cx"."folder_links"
  REFERENCING NEW TABLE AS new_rows FOR EACH STATEMENT EXECUTE FUNCTION authz_int."folder_project__folder_parent__tree_on_links1"();
CREATE TRIGGER "authz_folder_project__folder_parent__tree_on_links1_upd" AFTER UPDATE ON "cx"."folder_links"
  REFERENCING OLD TABLE AS old_rows NEW TABLE AS new_rows FOR EACH STATEMENT EXECUTE FUNCTION authz_int."folder_project__folder_parent__tree_on_links1"();
CREATE TRIGGER "authz_folder_project__folder_parent__tree_on_links1_del" AFTER DELETE ON "cx"."folder_links"
  REFERENCING OLD TABLE AS old_rows FOR EACH STATEMENT EXECUTE FUNCTION authz_int."folder_project__folder_parent__tree_on_links1"();
CREATE TRIGGER "authz_folder_project__folder_parent__tree_on_links1_trunc" AFTER TRUNCATE ON "cx"."folder_links"
  FOR EACH STATEMENT EXECUTE FUNCTION authz_int."folder_project__folder_parent__tree_on_truncate"();

-- backfill from the rows already there (unless the tree was kept)
DO $b$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_temp.authz_kept WHERE name = 'folder_project__folder_parent__tree') THEN
    PERFORM authz_int."folder_project__folder_parent__tree_rebuild"();
  END IF;
END $b$;

-- folder: each row with every ancestor it inherits from, through parent
CREATE TABLE authz_int."folder__parent__tree" (descendant text NOT NULL, ancestor text NOT NULL,
  PRIMARY KEY (descendant, ancestor));
CREATE INDEX ON authz_int."folder__parent__tree" (ancestor);
INSERT INTO authz_int.locks VALUES ('folder', 0) ON CONFLICT DO NOTHING;
-- kept from the last apply if its definition is the same: its rows are current
DO $k$ BEGIN
  IF to_regclass('authz_keep."folder__parent__tree"') IS NOT NULL THEN
    DROP TABLE authz_int."folder__parent__tree";
    ALTER TABLE authz_keep."folder__parent__tree" SET SCHEMA authz_int;
    INSERT INTO pg_temp.authz_kept VALUES ('folder__parent__tree') ON CONFLICT DO NOTHING;
  END IF;
END $k$;

-- every parent link, from every source
CREATE VIEW authz_int."folder__parent__tree_links" AS
  (SELECT 0 AS _link, ROW(r."org_id"::bigint, r."id"::bigint)::text AS _child, (CASE WHEN r."parent_type" = 'folder' THEN (CASE WHEN (r."org_id", r."parent_id") IS NOT NULL THEN ROW(r."org_id"::bigint, r."parent_id"::bigint)::text END) END) AS _parent FROM "cx"."folders" r WHERE (CASE WHEN r."parent_type" = 'folder' THEN (CASE WHEN (r."org_id", r."parent_id") IS NOT NULL THEN ROW(r."org_id"::bigint, r."parent_id"::bigint)::text END) END) IS NOT NULL)
  UNION ALL
  (SELECT 0 AS _link, (CASE WHEN (s."org_id", s."child_id") IS NOT NULL THEN ROW(s."org_id"::bigint, s."child_id"::bigint)::text END) AS _child, (CASE WHEN (s."org_id", s."parent_id") IS NOT NULL THEN ROW(s."org_id"::bigint, s."parent_id"::bigint)::text END) AS _parent FROM "cx"."folder_links" s WHERE (CASE WHEN (s."org_id", s."parent_id") IS NOT NULL THEN ROW(s."org_id"::bigint, s."parent_id"::bigint)::text END) IS NOT NULL AND (CASE WHEN (s."org_id", s."child_id") IS NOT NULL THEN ROW(s."org_id"::bigint, s."child_id"::bigint)::text END) IS NOT NULL);

-- walk up from the given rows; a link is followed only if its condition holds on
-- the child, and the parent exists and passes its type's where
CREATE FUNCTION authz_int."folder__parent__tree_compute"(p_ids text[]) RETURNS TABLE (o_descendant text, o_ancestor text)
LANGUAGE sql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
  WITH RECURSIVE up(_d, _a) AS (
    SELECT ROW(x."org_id"::bigint, x."id"::bigint)::text, ROW(x."org_id"::bigint, x."id"::bigint)::text FROM "cx"."folders" x WHERE (x."org_id", x."id") IN (SELECT (k.k)."org_id", (k.k)."id" FROM (SELECT x.id::authz_gen."folder__key" AS k FROM (SELECT unnest(p_ids) AS id) x) k)
    UNION
    SELECT up._d, e._parent
    FROM up
    -- one index lookup per step: joined plainly, a small table gets a full scan at every step
    -- (OFFSET 0 keeps the planner from turning this into a hash join)
    CROSS JOIN LATERAL (SELECT c.* FROM "cx"."folders" c WHERE (c."org_id", c."id") = (((up._a)::authz_gen."folder__key")."org_id", ((up._a)::authz_gen."folder__key")."id") OFFSET 0) c
    CROSS JOIN LATERAL (
      (SELECT x.* FROM (SELECT 0 AS _link, ROW(r."org_id"::bigint, r."id"::bigint)::text AS _child, (CASE WHEN r."parent_type" = 'folder' THEN (CASE WHEN (r."org_id", r."parent_id") IS NOT NULL THEN ROW(r."org_id"::bigint, r."parent_id"::bigint)::text END) END) AS _parent FROM "cx"."folders" r WHERE (CASE WHEN r."parent_type" = 'folder' THEN (CASE WHEN (r."org_id", r."parent_id") IS NOT NULL THEN ROW(r."org_id"::bigint, r."parent_id"::bigint)::text END) END) IS NOT NULL AND (r."org_id", r."id") = (((up._a)::authz_gen."folder__key")."org_id", ((up._a)::authz_gen."folder__key")."id")) x OFFSET 0)
      UNION ALL (SELECT x.* FROM (SELECT 0 AS _link, (CASE WHEN (s."org_id", s."child_id") IS NOT NULL THEN ROW(s."org_id"::bigint, s."child_id"::bigint)::text END) AS _child, (CASE WHEN (s."org_id", s."parent_id") IS NOT NULL THEN ROW(s."org_id"::bigint, s."parent_id"::bigint)::text END) AS _parent FROM "cx"."folder_links" s WHERE (CASE WHEN (s."org_id", s."parent_id") IS NOT NULL THEN ROW(s."org_id"::bigint, s."parent_id"::bigint)::text END) IS NOT NULL AND (CASE WHEN (s."org_id", s."child_id") IS NOT NULL THEN ROW(s."org_id"::bigint, s."child_id"::bigint)::text END) IS NOT NULL AND (s."org_id", s."child_id") = (((up._a)::authz_gen."folder__key")."org_id", ((up._a)::authz_gen."folder__key")."id")) x OFFSET 0)) e
    WHERE (e._link = 0)
      AND EXISTS (SELECT 1 FROM "cx"."folders" p WHERE (p."org_id", p."id") = (((e._parent)::authz_gen."folder__key")."org_id", ((e._parent)::authz_gen."folder__key")."id")))
  SELECT _d, _a FROM up
$f$;

-- what decides inheritance must be IMMUTABLE
DO $imm$
DECLARE d record;
BEGIN

  FOR d IN SELECT DISTINCT p.oid::regprocedure AS fn
           FROM pg_depend dep
           JOIN pg_rewrite w ON w.oid = dep.objid AND dep.classid = 'pg_rewrite'::regclass
           JOIN pg_proc p ON p.oid = dep.refobjid AND dep.refclassid = 'pg_proc'::regclass
           WHERE w.ev_class IN ('authz_int."folder__parent__tree_links"'::regclass) AND p.provolatile <> 'i' LOOP
    RAISE EXCEPTION 'line 32: a condition used for inheritance calls %, which is not IMMUTABLE; read tables with a subquery instead, so changes to them are tracked [AZ603]', d.fn;
  END LOOP;
END $imm$;

-- after a change to the links of p_ids alone (nothing inserted, deleted or renumbered), everything
-- below them (p_below, which includes them) keeps its stored rows among itself, and only rows to the
-- ancestors of p_ids, before or after, can change: to those, each row below now reaches whatever the
-- stored rows of the links leaving the part below lead to. A move of a folder with thousands below it
-- then rewrites (below it) x (its old and new ancestors) rows instead of recomputing every one. That
-- holds only if no link of p_ids, before or after, leads back into the part below them (checked here;
-- false means nothing was done and the caller recomputes). Plans are made for each call's arrays:
-- one made for a few rows would be ruinous for a big move
CREATE FUNCTION authz_int."folder__parent__tree_shift"(p_ids text[], p_below text[]) RETURNS boolean
LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT SET plan_cache_mode = force_custom_plan AS $f$
DECLARE touched text[];
BEGIN
  IF EXISTS (SELECT 1 FROM authz_int."folder__parent__tree" t JOIN unnest(p_below) b(id) ON b.id = t.ancestor
             WHERE t.descendant = ANY (p_ids) AND t.ancestor <> t.descendant) THEN
    RETURN false;
  END IF;
  IF EXISTS (SELECT 1 FROM unnest(p_ids) b(_y) JOIN "cx"."folders" c ON (c."org_id", c."id") = (((b._y)::authz_gen."folder__key")."org_id", ((b._y)::authz_gen."folder__key")."id")
             CROSS JOIN LATERAL (
               (SELECT x.* FROM (SELECT 0 AS _link, ROW(r."org_id"::bigint, r."id"::bigint)::text AS _child, (CASE WHEN r."parent_type" = 'folder' THEN (CASE WHEN (r."org_id", r."parent_id") IS NOT NULL THEN ROW(r."org_id"::bigint, r."parent_id"::bigint)::text END) END) AS _parent FROM "cx"."folders" r WHERE (CASE WHEN r."parent_type" = 'folder' THEN (CASE WHEN (r."org_id", r."parent_id") IS NOT NULL THEN ROW(r."org_id"::bigint, r."parent_id"::bigint)::text END) END) IS NOT NULL AND (r."org_id", r."id") = (((b._y)::authz_gen."folder__key")."org_id", ((b._y)::authz_gen."folder__key")."id")) x OFFSET 0)
      UNION ALL (SELECT x.* FROM (SELECT 0 AS _link, (CASE WHEN (s."org_id", s."child_id") IS NOT NULL THEN ROW(s."org_id"::bigint, s."child_id"::bigint)::text END) AS _child, (CASE WHEN (s."org_id", s."parent_id") IS NOT NULL THEN ROW(s."org_id"::bigint, s."parent_id"::bigint)::text END) AS _parent FROM "cx"."folder_links" s WHERE (CASE WHEN (s."org_id", s."parent_id") IS NOT NULL THEN ROW(s."org_id"::bigint, s."parent_id"::bigint)::text END) IS NOT NULL AND (CASE WHEN (s."org_id", s."child_id") IS NOT NULL THEN ROW(s."org_id"::bigint, s."child_id"::bigint)::text END) IS NOT NULL AND (s."org_id", s."child_id") = (((b._y)::authz_gen."folder__key")."org_id", ((b._y)::authz_gen."folder__key")."id")) x OFFSET 0)) e
             WHERE (e._link = 0) AND e._parent = ANY (p_below)) THEN
    RETURN false;
  END IF;
  -- the ancestors of p_ids before (stored) and after (through their links now): no others change
  touched := ARRAY(
    SELECT t.ancestor FROM authz_int."folder__parent__tree" t WHERE t.descendant = ANY (p_ids) AND t.ancestor <> t.descendant
    UNION
    SELECT u.ancestor FROM unnest(p_ids) b(_y) JOIN "cx"."folders" c ON (c."org_id", c."id") = (((b._y)::authz_gen."folder__key")."org_id", ((b._y)::authz_gen."folder__key")."id")
    CROSS JOIN LATERAL (
      (SELECT x.* FROM (SELECT 0 AS _link, ROW(r."org_id"::bigint, r."id"::bigint)::text AS _child, (CASE WHEN r."parent_type" = 'folder' THEN (CASE WHEN (r."org_id", r."parent_id") IS NOT NULL THEN ROW(r."org_id"::bigint, r."parent_id"::bigint)::text END) END) AS _parent FROM "cx"."folders" r WHERE (CASE WHEN r."parent_type" = 'folder' THEN (CASE WHEN (r."org_id", r."parent_id") IS NOT NULL THEN ROW(r."org_id"::bigint, r."parent_id"::bigint)::text END) END) IS NOT NULL AND (r."org_id", r."id") = (((b._y)::authz_gen."folder__key")."org_id", ((b._y)::authz_gen."folder__key")."id")) x OFFSET 0)
      UNION ALL (SELECT x.* FROM (SELECT 0 AS _link, (CASE WHEN (s."org_id", s."child_id") IS NOT NULL THEN ROW(s."org_id"::bigint, s."child_id"::bigint)::text END) AS _child, (CASE WHEN (s."org_id", s."parent_id") IS NOT NULL THEN ROW(s."org_id"::bigint, s."parent_id"::bigint)::text END) AS _parent FROM "cx"."folder_links" s WHERE (CASE WHEN (s."org_id", s."parent_id") IS NOT NULL THEN ROW(s."org_id"::bigint, s."parent_id"::bigint)::text END) IS NOT NULL AND (CASE WHEN (s."org_id", s."child_id") IS NOT NULL THEN ROW(s."org_id"::bigint, s."child_id"::bigint)::text END) IS NOT NULL AND (s."org_id", s."child_id") = (((b._y)::authz_gen."folder__key")."org_id", ((b._y)::authz_gen."folder__key")."id")) x OFFSET 0)) e
    JOIN authz_int."folder__parent__tree" u ON u.descendant = e._parent
    WHERE (e._link = 0));
  WITH below AS MATERIALIZED (SELECT x AS _y FROM unnest(p_below) x),
  -- links from the part below to outside it, as they are now
  exits AS MATERIALIZED (
    SELECT e._child AS y, e._parent AS p
    FROM below JOIN "cx"."folders" c ON (c."org_id", c."id") = (((below._y)::authz_gen."folder__key")."org_id", ((below._y)::authz_gen."folder__key")."id")
    CROSS JOIN LATERAL (
      (SELECT x.* FROM (SELECT 0 AS _link, ROW(r."org_id"::bigint, r."id"::bigint)::text AS _child, (CASE WHEN r."parent_type" = 'folder' THEN (CASE WHEN (r."org_id", r."parent_id") IS NOT NULL THEN ROW(r."org_id"::bigint, r."parent_id"::bigint)::text END) END) AS _parent FROM "cx"."folders" r WHERE (CASE WHEN r."parent_type" = 'folder' THEN (CASE WHEN (r."org_id", r."parent_id") IS NOT NULL THEN ROW(r."org_id"::bigint, r."parent_id"::bigint)::text END) END) IS NOT NULL AND (r."org_id", r."id") = (((below._y)::authz_gen."folder__key")."org_id", ((below._y)::authz_gen."folder__key")."id")) x OFFSET 0)
      UNION ALL (SELECT x.* FROM (SELECT 0 AS _link, (CASE WHEN (s."org_id", s."child_id") IS NOT NULL THEN ROW(s."org_id"::bigint, s."child_id"::bigint)::text END) AS _child, (CASE WHEN (s."org_id", s."parent_id") IS NOT NULL THEN ROW(s."org_id"::bigint, s."parent_id"::bigint)::text END) AS _parent FROM "cx"."folder_links" s WHERE (CASE WHEN (s."org_id", s."parent_id") IS NOT NULL THEN ROW(s."org_id"::bigint, s."parent_id"::bigint)::text END) IS NOT NULL AND (CASE WHEN (s."org_id", s."child_id") IS NOT NULL THEN ROW(s."org_id"::bigint, s."child_id"::bigint)::text END) IS NOT NULL AND (s."org_id", s."child_id") = (((below._y)::authz_gen."folder__key")."org_id", ((below._y)::authz_gen."folder__key")."id")) x OFFSET 0)) e
    WHERE (e._link = 0)),
  -- each row below: the touched ancestors it now reaches, through the exits it reaches
  fresh AS MATERIALIZED (
    SELECT DISTINCT d.descendant AS d, u.ancestor AS a
    FROM exits
    JOIN authz_int."folder__parent__tree" u ON u.descendant = exits.p AND u.ancestor = ANY (touched)
    JOIN authz_int."folder__parent__tree" d ON d.ancestor = exits.y
    WHERE NOT EXISTS (SELECT 1 FROM below b WHERE b._y = exits.p)),
  stale AS (
    DELETE FROM authz_int."folder__parent__tree" t
    WHERE t.ancestor = ANY (touched) AND t.descendant IN (SELECT _y FROM below)
      AND NOT EXISTS (SELECT 1 FROM fresh o WHERE o.d = t.descendant AND o.a = t.ancestor))
  INSERT INTO authz_int."folder__parent__tree" (descendant, ancestor) SELECT d, a FROM fresh ON CONFLICT DO NOTHING;
  RETURN true;
END $f$;

-- recompute the given rows and everything linked below them; p_shift: only their own links changed
CREATE FUNCTION authz_int."folder__parent__tree_refresh"(p_ids text[], p_shift boolean DEFAULT false) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $f$
DECLARE affected text[];
BEGIN
  IF coalesce(cardinality(p_ids), 0) = 0 THEN RETURN; END IF;
  UPDATE authz_int.locks SET n = n + 1 WHERE type IN ('folder');
  WITH RECURSIVE down(id) AS (
    SELECT x FROM unnest(p_ids) AS x WHERE x IS NOT NULL
    UNION
    SELECT e._child FROM down CROSS JOIN LATERAL (
      (SELECT x.* FROM (SELECT 0 AS _link, ROW(r."org_id"::bigint, r."id"::bigint)::text AS _child, (CASE WHEN r."parent_type" = 'folder' THEN (CASE WHEN (r."org_id", r."parent_id") IS NOT NULL THEN ROW(r."org_id"::bigint, r."parent_id"::bigint)::text END) END) AS _parent FROM "cx"."folders" r WHERE (CASE WHEN r."parent_type" = 'folder' THEN (CASE WHEN (r."org_id", r."parent_id") IS NOT NULL THEN ROW(r."org_id"::bigint, r."parent_id"::bigint)::text END) END) IS NOT NULL AND (r."org_id", r."parent_id") = (((down.id)::authz_gen."folder__key")."org_id", ((down.id)::authz_gen."folder__key")."id") AND r."parent_type" = 'folder') x OFFSET 0)
      UNION ALL (SELECT x.* FROM (SELECT 0 AS _link, (CASE WHEN (s."org_id", s."child_id") IS NOT NULL THEN ROW(s."org_id"::bigint, s."child_id"::bigint)::text END) AS _child, (CASE WHEN (s."org_id", s."parent_id") IS NOT NULL THEN ROW(s."org_id"::bigint, s."parent_id"::bigint)::text END) AS _parent FROM "cx"."folder_links" s WHERE (CASE WHEN (s."org_id", s."parent_id") IS NOT NULL THEN ROW(s."org_id"::bigint, s."parent_id"::bigint)::text END) IS NOT NULL AND (CASE WHEN (s."org_id", s."child_id") IS NOT NULL THEN ROW(s."org_id"::bigint, s."child_id"::bigint)::text END) IS NOT NULL AND (s."org_id", s."parent_id") = (((down.id)::authz_gen."folder__key")."org_id", ((down.id)::authz_gen."folder__key")."id")) x OFFSET 0)) e)
  SELECT array_agg(id) INTO affected FROM down;
  IF NOT (p_shift AND authz_int."folder__parent__tree_shift"(p_ids, affected)) THEN
    DELETE FROM authz_int."folder__parent__tree" WHERE descendant = ANY (affected);
    INSERT INTO authz_int."folder__parent__tree" (descendant, ancestor)
    SELECT o_descendant, o_ancestor FROM authz_int."folder__parent__tree_compute"(affected);
  END IF;
  PERFORM authz_int.changed('folder', affected::text[], 'inheritance');
END $f$;

-- recompute everything (backfill, TRUNCATE), 10000 rows at a time
CREATE FUNCTION authz_int."folder__parent__tree_rebuild"() RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $f$
DECLARE batch text[];
BEGIN
  UPDATE authz_int.locks SET n = n + 1 WHERE type IN ('folder');
  DELETE FROM authz_int."folder__parent__tree";
  FOR batch IN SELECT array_agg(k.k) FROM (SELECT ROW("cx"."folders"."org_id"::bigint, "cx"."folders"."id"::bigint)::text AS k, row_number() OVER () AS n FROM "cx"."folders") k GROUP BY (k.n - 1) / 10000 LOOP
    INSERT INTO authz_int."folder__parent__tree" (descendant, ancestor)
    SELECT o_descendant, o_ancestor FROM authz_int."folder__parent__tree_compute"(batch);
  END LOOP;
END $f$;
CREATE FUNCTION authz_int."folder__parent__tree_on_truncate"() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $f$
BEGIN PERFORM authz_int."folder__parent__tree_rebuild"(); RETURN NULL; END $f$;

-- what a rebuild would give against what is stored, 10000 rows at a time; then nothing stored for a row
-- that is gone
CREATE FUNCTION authz_int."folder__parent__tree_verify"() RETURNS boolean
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
DECLARE batch text[];
BEGIN
  FOR batch IN SELECT array_agg(k.k) FROM (SELECT ROW("cx"."folders"."org_id"::bigint, "cx"."folders"."id"::bigint)::text AS k, row_number() OVER () AS n FROM "cx"."folders") k GROUP BY (k.n - 1) / 10000 LOOP
    IF EXISTS (WITH fresh AS MATERIALIZED (SELECT o_descendant AS d, o_ancestor AS a FROM authz_int."folder__parent__tree_compute"(batch)),
                    stored AS MATERIALIZED (SELECT descendant AS d, ancestor AS a FROM authz_int."folder__parent__tree"
                                            WHERE descendant = ANY (batch))
               (SELECT d, a FROM fresh EXCEPT SELECT d, a FROM stored)
               UNION ALL
               (SELECT d, a FROM stored EXCEPT SELECT d, a FROM fresh)) THEN
      RETURN false;
    END IF;
  END LOOP;
  IF EXISTS (SELECT 1 FROM authz_int."folder__parent__tree" s
             WHERE NOT EXISTS (SELECT 1 FROM "cx"."folders" x WHERE (x."org_id", x."id") = (((s.descendant)::authz_gen."folder__key")."org_id", ((s.descendant)::authz_gen."folder__key")."id"))) THEN
    RETURN false;
  END IF;
  RETURN true;
END $f$;

-- the tree's own columns may not loop (links through tables may: they add nothing)
CREATE VIEW authz_int."folder__parent__tree_parents" AS
  SELECT ROW(r."org_id"::bigint, r."id"::bigint)::text AS _child, (CASE WHEN r."parent_type" = 'folder' THEN (CASE WHEN (r."org_id", r."parent_id") IS NOT NULL THEN ROW(r."org_id"::bigint, r."parent_id"::bigint)::text END) END) AS _parent FROM "cx"."folders" r WHERE (CASE WHEN r."parent_type" = 'folder' THEN (CASE WHEN (r."org_id", r."parent_id") IS NOT NULL THEN ROW(r."org_id"::bigint, r."parent_id"::bigint)::text END) END) IS NOT NULL;
CREATE FUNCTION authz_int."folder__parent__tree_check_loops"(p_ids text[]) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $f$
DECLARE bad text;
BEGIN
  WITH RECURSIVE up(start, id) AS (
    SELECT e._child, e._parent FROM authz_int."folder__parent__tree_parents" e WHERE e._child = ANY (p_ids)
    UNION
    SELECT up.start, e._parent FROM up CROSS JOIN LATERAL (
      (SELECT x.* FROM (SELECT ROW(r."org_id"::bigint, r."id"::bigint)::text AS _child, (CASE WHEN r."parent_type" = 'folder' THEN (CASE WHEN (r."org_id", r."parent_id") IS NOT NULL THEN ROW(r."org_id"::bigint, r."parent_id"::bigint)::text END) END) AS _parent FROM "cx"."folders" r WHERE (CASE WHEN r."parent_type" = 'folder' THEN (CASE WHEN (r."org_id", r."parent_id") IS NOT NULL THEN ROW(r."org_id"::bigint, r."parent_id"::bigint)::text END) END) IS NOT NULL AND (r."org_id", r."id") = (((up.id)::authz_gen."folder__key")."org_id", ((up.id)::authz_gen."folder__key")."id")) x OFFSET 0)) e)
  SELECT start::text INTO bad FROM up WHERE id = start LIMIT 1;
  IF bad IS NOT NULL THEN
    RAISE EXCEPTION 'folder % cannot be moved inside itself', bad USING ERRCODE = 'check_violation', HINT = 'rowstile help AZ713';
  END IF;
END $f$;

-- rows inserted, deleted, moved, or whose id or conditions change
CREATE FUNCTION authz_int."folder__parent__tree_on_rows"() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $f$
DECLARE ids text[]; shift boolean := false;
BEGIN
  IF TG_OP = 'INSERT' THEN
    ids := ARRAY(SELECT ROW(n."org_id"::bigint, n."id"::bigint)::text FROM new_rows n);
  ELSIF TG_OP = 'UPDATE' THEN
    -- rows whose id changed: the old id disappears and the new one appears
    ids := ARRAY(
      SELECT ROW(o."org_id"::bigint, o."id"::bigint)::text FROM old_rows o WHERE NOT EXISTS (SELECT 1 FROM new_rows n WHERE ROW(n."org_id"::bigint, n."id"::bigint)::text = ROW(o."org_id"::bigint, o."id"::bigint)::text)
      UNION SELECT ROW(n."org_id"::bigint, n."id"::bigint)::text FROM new_rows n WHERE NOT EXISTS (SELECT 1 FROM old_rows o WHERE ROW(o."org_id"::bigint, o."id"::bigint)::text = ROW(n."org_id"::bigint, n."id"::bigint)::text));
    shift := cardinality(ids) = 0;
    ids := ARRAY(
      SELECT ROW(n."org_id"::bigint, n."id"::bigint)::text FROM new_rows n JOIN old_rows o ON ROW(o."org_id"::bigint, o."id"::bigint)::text = ROW(n."org_id"::bigint, n."id"::bigint)::text
      WHERE n."org_id" IS DISTINCT FROM o."org_id"
         OR n."parent_id" IS DISTINCT FROM o."parent_id"
         OR n."parent_type" IS DISTINCT FROM o."parent_type"
      UNION SELECT unnest(ids));
  ELSE
    ids := ARRAY(SELECT ROW(o."org_id"::bigint, o."id"::bigint)::text FROM old_rows o);
  END IF;
  IF cardinality(ids) > 0 THEN
    UPDATE authz_int.locks SET n = n + 1 WHERE type IN ('folder');
  IF TG_OP <> 'DELETE' THEN PERFORM authz_int."folder__parent__tree_check_loops"(ids); END IF;
    PERFORM authz_int."folder__parent__tree_refresh"(ids, shift);
  END IF;
  RETURN NULL;
END $f$;
CREATE TRIGGER "authz_folder__parent__tree_ins" AFTER INSERT ON "cx"."folders"
  REFERENCING NEW TABLE AS new_rows FOR EACH STATEMENT EXECUTE FUNCTION authz_int."folder__parent__tree_on_rows"();
CREATE TRIGGER "authz_folder__parent__tree_upd" AFTER UPDATE ON "cx"."folders"
  REFERENCING OLD TABLE AS old_rows NEW TABLE AS new_rows FOR EACH STATEMENT EXECUTE FUNCTION authz_int."folder__parent__tree_on_rows"();
CREATE TRIGGER "authz_folder__parent__tree_del" AFTER DELETE ON "cx"."folders"
  REFERENCING OLD TABLE AS old_rows FOR EACH STATEMENT EXECUTE FUNCTION authz_int."folder__parent__tree_on_rows"();
CREATE TRIGGER "authz_folder__parent__tree_trunc" AFTER TRUNCATE ON "cx"."folders"
  FOR EACH STATEMENT EXECUTE FUNCTION authz_int."folder__parent__tree_on_truncate"();

-- links stored in cx.folder_links
CREATE FUNCTION authz_int."folder__parent__tree_on_links1"() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $f$
BEGIN
  -- one refresh for old and new links together: each refresh expects the rest to be current
  IF TG_OP = 'INSERT' THEN PERFORM authz_int."folder__parent__tree_refresh"(ARRAY(SELECT (CASE WHEN (n."org_id", n."child_id") IS NOT NULL THEN ROW(n."org_id"::bigint, n."child_id"::bigint)::text END) FROM new_rows n), true);
  ELSIF TG_OP = 'DELETE' THEN PERFORM authz_int."folder__parent__tree_refresh"(ARRAY(SELECT (CASE WHEN (o."org_id", o."child_id") IS NOT NULL THEN ROW(o."org_id"::bigint, o."child_id"::bigint)::text END) FROM old_rows o), true);
  ELSE PERFORM authz_int."folder__parent__tree_refresh"(ARRAY(SELECT (CASE WHEN (n."org_id", n."child_id") IS NOT NULL THEN ROW(n."org_id"::bigint, n."child_id"::bigint)::text END) FROM new_rows n UNION SELECT (CASE WHEN (o."org_id", o."child_id") IS NOT NULL THEN ROW(o."org_id"::bigint, o."child_id"::bigint)::text END) FROM old_rows o), true);
  END IF;
  RETURN NULL;
END $f$;
CREATE TRIGGER "authz_folder__parent__tree_on_links1_ins" AFTER INSERT ON "cx"."folder_links"
  REFERENCING NEW TABLE AS new_rows FOR EACH STATEMENT EXECUTE FUNCTION authz_int."folder__parent__tree_on_links1"();
CREATE TRIGGER "authz_folder__parent__tree_on_links1_upd" AFTER UPDATE ON "cx"."folder_links"
  REFERENCING OLD TABLE AS old_rows NEW TABLE AS new_rows FOR EACH STATEMENT EXECUTE FUNCTION authz_int."folder__parent__tree_on_links1"();
CREATE TRIGGER "authz_folder__parent__tree_on_links1_del" AFTER DELETE ON "cx"."folder_links"
  REFERENCING OLD TABLE AS old_rows FOR EACH STATEMENT EXECUTE FUNCTION authz_int."folder__parent__tree_on_links1"();
CREATE TRIGGER "authz_folder__parent__tree_on_links1_trunc" AFTER TRUNCATE ON "cx"."folder_links"
