           nullif(current_setting('authz_ctx.reason', true), '')
    FROM (SELECT 'unrelate' AS action, 'team' AS ot, (CASE WHEN (x."org_id", x."parent_slug") IS NOT NULL THEN ROW(x."org_id"::bigint, x."parent_slug"::text)::text END) AS oid, 'member' AS rel, 'team' AS st, (CASE WHEN (x."org_id", x."slug") IS NOT NULL THEN ROW(x."org_id"::bigint, x."slug"::text)::text END) AS sid, 'member' AS sr FROM old_rows x WHERE true) c;
    PERFORM authz_int.changed(c.ot, array_agg(DISTINCT c.oid), 'relationship') FROM (SELECT 'unrelate' AS action, 'team' AS ot, (CASE WHEN (x."org_id", x."parent_slug") IS NOT NULL THEN ROW(x."org_id"::bigint, x."parent_slug"::text)::text END) AS oid, 'member' AS rel, 'team' AS st, (CASE WHEN (x."org_id", x."slug") IS NOT NULL THEN ROW(x."org_id"::bigint, x."slug"::text)::text END) AS sid, 'member' AS sr FROM old_rows x WHERE true) c GROUP BY c.ot;
