    EXECUTE 'CREATE TRIGGER "authz_file_col_audit_ins" AFTER INSERT ON "cx"."files" REFERENCING NEW TABLE AS new_rows FOR EACH STATEMENT EXECUTE FUNCTION authz_int."file__col_audit_ins"()';
  ELSE
    RAISE NOTICE '"cx"."files" is not a table: changes to it are not audited or fed (audit)';
  END IF;
END $tr$;
CREATE FUNCTION authz_int."file__col_audit_upd"() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
BEGIN
    PERFORM authz_int.changed('file', ARRAY(SELECT ROW(n."org_id"::bigint, n."id"::bigint)::text FROM new_rows n UNION SELECT ROW(o."org_id"::bigint, o."id"::bigint)::text FROM old_rows o), 'update');
    -- a partitioned table: the rows this update put in another partition, which the row trigger never sees
    IF (SELECT relkind FROM pg_class WHERE oid = TG_RELID) = 'p' THEN
      INSERT INTO authz.audit (db_role, user_id, acting_user, action, object_type, object_id, relation, subject_id, detail, reason)
      SELECT authz_int.caller_role(), authz_int.actor(), nullif(current_setting('authz.acting_user', true), ''), 'relate', 'file', ROW(n."org_id"::bigint, n."id"::bigint)::text, 'folder', n."org_id"::text, jsonb_build_object('column', 'org_id', 'was', o."org_id"), nullif(current_setting('authz_ctx.reason', true), '')
      FROM old_rows o JOIN new_rows n ON ROW(n."org_id"::bigint, n."id"::bigint)::text = ROW(o."org_id"::bigint, o."id"::bigint)::text
      WHERE n."org_id" IS DISTINCT FROM o."org_id" AND NOT EXISTS (
        SELECT 1 FROM authz.audit a WHERE a.txid = txid_current() AND a.action = 'relate' AND a.object_type = 'file'
          AND a.object_id = ROW(n."org_id"::bigint, n."id"::bigint)::text AND a.relation = 'folder' AND a.detail->>'column' = 'org_id'
          AND a.subject_id IS NOT DISTINCT FROM n."org_id"::text AND a.detail->'was' IS NOT DISTINCT FROM to_jsonb(o."org_id"));
      INSERT INTO authz.audit (db_role, user_id, acting_user, action, object_type, object_id, relation, subject_id, detail, reason)
      SELECT authz_int.caller_role(), authz_int.actor(), nullif(current_setting('authz.acting_user', true), ''), 'relate', 'file', ROW(n."org_id"::bigint, n."id"::bigint)::text, 'folder', n."folder_id"::text, jsonb_build_object('column', 'folder_id', 'was', o."folder_id"), nullif(current_setting('authz_ctx.reason', true), '')
      FROM old_rows o JOIN new_rows n ON ROW(n."org_id"::bigint, n."id"::bigint)::text = ROW(o."org_id"::bigint, o."id"::bigint)::text
      WHERE n."folder_id" IS DISTINCT FROM o."folder_id" AND NOT EXISTS (
        SELECT 1 FROM authz.audit a WHERE a.txid = txid_current() AND a.action = 'relate' AND a.object_type = 'file'
          AND a.object_id = ROW(n."org_id"::bigint, n."id"::bigint)::text AND a.relation = 'folder' AND a.detail->>'column' = 'folder_id'
          AND a.subject_id IS NOT DISTINCT FROM n."folder_id"::text AND a.detail->'was' IS NOT DISTINCT FROM to_jsonb(o."folder_id"));
      INSERT INTO authz.audit (db_role, user_id, acting_user, action, object_type, object_id, relation, subject_id, detail, reason)
      SELECT authz_int.caller_role(), authz_int.actor(), nullif(current_setting('authz.acting_user', true), ''), 'relate', 'file', ROW(n."org_id"::bigint, n."id"::bigint)::text, 'owner', n."owner_id"::text, jsonb_build_object('column', 'owner_id', 'was', o."owner_id"), nullif(current_setting('authz_ctx.reason', true), '')
      FROM old_rows o JOIN new_rows n ON ROW(n."org_id"::bigint, n."id"::bigint)::text = ROW(o."org_id"::bigint, o."id"::bigint)::text
      WHERE n."owner_id" IS DISTINCT FROM o."owner_id" AND NOT EXISTS (
        SELECT 1 FROM authz.audit a WHERE a.txid = txid_current() AND a.action = 'relate' AND a.object_type = 'file'
          AND a.object_id = ROW(n."org_id"::bigint, n."id"::bigint)::text AND a.relation = 'owner' AND a.detail->>'column' = 'owner_id'
          AND a.subject_id IS NOT DISTINCT FROM n."owner_id"::text AND a.detail->'was' IS NOT DISTINCT FROM to_jsonb(o."owner_id"));
      INSERT INTO authz.audit (db_role, user_id, acting_user, action, object_type, object_id, relation, subject_id, detail, reason)
      SELECT authz_int.caller_role(), authz_int.actor(), nullif(current_setting('authz.acting_user', true), ''), 'relate', 'file', ROW(n."org_id"::bigint, n."id"::bigint)::text, 'uploader', n."uploaded_by"::text, jsonb_build_object('column', 'uploaded_by', 'was', o."uploaded_by"), nullif(current_setting('authz_ctx.reason', true), '')
      FROM old_rows o JOIN new_rows n ON ROW(n."org_id"::bigint, n."id"::bigint)::text = ROW(o."org_id"::bigint, o."id"::bigint)::text
      WHERE n."uploaded_by" IS DISTINCT FROM o."uploaded_by" AND NOT EXISTS (
        SELECT 1 FROM authz.audit a WHERE a.txid = txid_current() AND a.action = 'relate' AND a.object_type = 'file'
          AND a.object_id = ROW(n."org_id"::bigint, n."id"::bigint)::text AND a.relation = 'uploader' AND a.detail->>'column' = 'uploaded_by'
          AND a.subject_id IS NOT DISTINCT FROM n."uploaded_by"::text AND a.detail->'was' IS NOT DISTINCT FROM to_jsonb(o."uploaded_by"));
    END IF;
  RETURN NULL;
END $f$;
-- @object trigger "authz_file_col_audit_upd" ON "cx"."files"
DO $tr$ BEGIN
  IF (SELECT relkind FROM pg_class WHERE oid = '"cx"."files"'::regclass) IN ('r', 'p') THEN
    EXECUTE 'CREATE TRIGGER "authz_file_col_audit_upd" AFTER UPDATE ON "cx"."files" REFERENCING OLD TABLE AS old_rows NEW TABLE AS new_rows FOR EACH STATEMENT EXECUTE FUNCTION authz_int."file__col_audit_upd"()';
  ELSE
    RAISE NOTICE '"cx"."files" is not a table: changes to it are not audited or fed (audit)';
  END IF;
END $tr$;
