-- one audit row per changed relationship column (a row trigger, so it also works when the key changes)
CREATE FUNCTION authz_int."file__col_audit_row"() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
BEGIN
  IF NEW."org_id" IS DISTINCT FROM OLD."org_id" THEN
    INSERT INTO authz.audit (db_role, user_id, acting_user, action, object_type, object_id, relation, subject_id, detail, reason)
    VALUES (authz_int.caller_role(), authz_int.actor(), nullif(current_setting('authz.acting_user', true), ''), 'relate', 'file', ROW(NEW."org_id"::bigint, NEW."id"::bigint)::text, 'folder', NEW."org_id"::text, jsonb_build_object('column', 'org_id', 'was', OLD."org_id"), nullif(current_setting('authz_ctx.reason', true), ''));
  END IF;
  IF NEW."folder_id" IS DISTINCT FROM OLD."folder_id" THEN
    INSERT INTO authz.audit (db_role, user_id, acting_user, action, object_type, object_id, relation, subject_id, detail, reason)
    VALUES (authz_int.caller_role(), authz_int.actor(), nullif(current_setting('authz.acting_user', true), ''), 'relate', 'file', ROW(NEW."org_id"::bigint, NEW."id"::bigint)::text, 'folder', NEW."folder_id"::text, jsonb_build_object('column', 'folder_id', 'was', OLD."folder_id"), nullif(current_setting('authz_ctx.reason', true), ''));
  END IF;
  IF NEW."owner_id" IS DISTINCT FROM OLD."owner_id" THEN
    INSERT INTO authz.audit (db_role, user_id, acting_user, action, object_type, object_id, relation, subject_id, detail, reason)
    VALUES (authz_int.caller_role(), authz_int.actor(), nullif(current_setting('authz.acting_user', true), ''), 'relate', 'file', ROW(NEW."org_id"::bigint, NEW."id"::bigint)::text, 'owner', NEW."owner_id"::text, jsonb_build_object('column', 'owner_id', 'was', OLD."owner_id"), nullif(current_setting('authz_ctx.reason', true), ''));
  END IF;
  IF NEW."uploaded_by" IS DISTINCT FROM OLD."uploaded_by" THEN
    INSERT INTO authz.audit (db_role, user_id, acting_user, action, object_type, object_id, relation, subject_id, detail, reason)
    VALUES (authz_int.caller_role(), authz_int.actor(), nullif(current_setting('authz.acting_user', true), ''), 'relate', 'file', ROW(NEW."org_id"::bigint, NEW."id"::bigint)::text, 'uploader', NEW."uploaded_by"::text, jsonb_build_object('column', 'uploaded_by', 'was', OLD."uploaded_by"), nullif(current_setting('authz_ctx.reason', true), ''));
  END IF;
  RETURN NULL;
END $f$;
-- @object trigger "authz_file_col_audit_row" ON "cx"."files"
DO $tr$ BEGIN
  IF (SELECT relkind FROM pg_class WHERE oid = '"cx"."files"'::regclass) IN ('r', 'p') THEN
    EXECUTE 'CREATE TRIGGER "authz_file_col_audit_row" AFTER UPDATE ON "cx"."files" FOR EACH ROW WHEN (OLD."org_id" IS DISTINCT FROM NEW."org_id" OR OLD."folder_id" IS DISTINCT FROM NEW."folder_id" OR OLD."owner_id" IS DISTINCT FROM NEW."owner_id" OR OLD."uploaded_by" IS DISTINCT FROM NEW."uploaded_by") EXECUTE FUNCTION authz_int."file__col_audit_row"()';
  ELSE
    RAISE NOTICE '"cx"."files" is not a table: changes to it are not audited or fed (audit)';
  END IF;
END $tr$;

