-- team.member (line 18)
CREATE VIEW authz_int."team__member" AS
  SELECT x.id FROM (
  WITH RECURSIVE m(id) AS (
    SELECT id FROM (
  (SELECT (CASE WHEN (s."org_id", s."team_slug") IS NOT NULL THEN ROW(s."org_id"::bigint, s."team_slug"::text)::text END) AS id FROM "cx"."team_members" s WHERE s."user_id" = (SELECT authz.uid()))
  UNION ALL
  (SELECT (CASE WHEN (s."org_id", s."team_slug") IS NOT NULL THEN ROW(s."org_id"::bigint, s."team_slug"::text)::text END) AS id FROM "cx"."team_bots" s WHERE s."bot_id" = (SELECT authz_int."bot__me"()))) d
    UNION
    SELECT e.obj FROM (
  (SELECT (CASE WHEN (s."org_id", s."parent_slug") IS NOT NULL THEN ROW(s."org_id"::bigint, s."parent_slug"::text)::text END) AS obj, (CASE WHEN (s."org_id", s."slug") IS NOT NULL THEN ROW(s."org_id"::bigint, s."slug"::text)::text END) AS subj FROM "cx"."teams" s WHERE (CASE WHEN (s."org_id", s."slug") IS NOT NULL THEN ROW(s."org_id"::bigint, s."slug"::text)::text END) IS NOT NULL AND (CASE WHEN (s."org_id", s."parent_slug") IS NOT NULL THEN ROW(s."org_id"::bigint, s."parent_slug"::text)::text END) IS NOT NULL)
  UNION ALL
  (SELECT g.object_id::text AS obj, g.subject_id::text AS subj FROM authz.shares g WHERE g.object_type = 'team' AND g.relation = 'member' AND g.subject_type = 'team' AND g.subject_relation = 'member' AND (g.expires_at IS NULL OR g.expires_at > now()) AND (g.starts_at IS NULL OR g.starts_at <= now()) AND g.caveat IS NULL)) e JOIN m ON e.subj = m.id
    WHERE EXISTS (SELECT 1 FROM "cx"."teams" w WHERE (w."org_id", w."slug") = (((m.id)::authz_gen."team__key")."org_id", ((m.id)::authz_gen."team__key")."slug") AND coalesce((not disbanded), false)))
  SELECT id FROM m) x
  WHERE EXISTS (SELECT 1 FROM "cx"."teams" w WHERE (w."org_id", w."slug") = (((x.id)::authz_gen."team__key")."org_id", ((x.id)::authz_gen."team__key")."slug") AND coalesce((not disbanded), false));
CREATE VIEW authz_gen."team__member" WITH (security_barrier) AS SELECT id FROM authz_int."team__member";

-- team.member for the user signed in, as an array (reads ask once per statement)
CREATE FUNCTION authz_gen."team__member__ids"() RETURNS text[]
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
BEGIN
  RETURN ARRAY(SELECT id FROM authz_int."team__member");
END $f$;

