ALTER TABLE "cx"."files" ENABLE ROW LEVEL SECURITY;
-- its partitions and the tables that inherit from it: row-level security on, with no policies of their own,
-- so they are read and written through it only (read directly, they would skip its rules and triggers)
DO $rls$
DECLARE c regclass;
BEGIN
  FOR c IN WITH RECURSIVE d(oid) AS (
             SELECT i.inhrelid FROM pg_catalog.pg_inherits i WHERE i.inhparent = '"cx"."files"'::regclass
             UNION SELECT i.inhrelid FROM pg_catalog.pg_inherits i JOIN d ON i.inhparent = d.oid)
           SELECT d.oid::regclass FROM d JOIN pg_catalog.pg_class k ON k.oid = d.oid WHERE NOT k.relrowsecurity LOOP
    EXECUTE format('ALTER TABLE %s ENABLE ROW LEVEL SECURITY', c);
  END LOOP;
END $rls$;

CREATE FUNCTION authz_gen."cx.files:insert:items"(p_row "cx"."files") RETURNS boolean[]
LANGUAGE sql STABLE
BEGIN ATOMIC
  SELECT ARRAY[
    coalesce((coalesce((owner_id = (SELECT authz.uid())), false)
    AND authz_gen."folder__edit__has"((CASE WHEN ("files"."org_id", "files"."folder_id") IS NOT NULL THEN ROW("files"."org_id"::bigint, "files"."folder_id"::bigint)::text END))), false),
    coalesce((SELECT authz_int.scope_cmd('cx.files', 'insert')), false),
    coalesce(true, false),
    coalesce(authz_gen."folder__edit__has"((CASE WHEN ("files"."org_id", "files"."folder_id") IS NOT NULL THEN ROW("files"."org_id"::bigint, "files"."folder_id"::bigint)::text END)), false),
    coalesce(coalesce((owner_id = (SELECT authz.uid())), false), false)]
  FROM (SELECT (p_row).*) AS "files";
END;

CREATE FUNCTION authz_gen."cx.files:insert:why"(p_row "cx"."files") RETURNS SETOF text
LANGUAGE plpgsql STABLE SET search_path FROM CURRENT AS $f$
#variable_conflict use_column
DECLARE v boolean[] := authz_gen."cx.files:insert:items"(p_row); v_t record;
BEGIN
  RETURN NEXT CASE WHEN v[1] THEN 'yes  ' ELSE 'no   ' END || 'insert : folder.edit and {owner_id = authz.uid()}  (' || coalesce((SELECT l.loc FROM authz_gen.policy_lines l WHERE l.what = 'rule cx.files insert'), '?') || ')';
  IF NOT v[2] THEN RETURN NEXT '  no   the sign-in''s scopes do not allow insert on cx.files'; END IF;
  RETURN NEXT CASE WHEN v[4] THEN '  yes  ' ELSE '  no   ' END || 'folder.edit';
  IF NOT v[4] THEN
    FOR v_t IN SELECT DISTINCT x.id FROM (SELECT ((CASE WHEN ("files"."org_id", "files"."folder_id") IS NOT NULL THEN ROW("files"."org_id"::bigint, "files"."folder_id"::bigint)::text END))::text AS id FROM (SELECT (p_row).*) AS "files") x WHERE x.id IS NOT NULL ORDER BY 1 LIMIT 3 LOOP
      RETURN QUERY SELECT '    ' || l FROM authz.explain('folder', v_t.id, 'edit') l LIMIT 20;
    END LOOP;
  END IF;
  RETURN NEXT CASE WHEN v[5] THEN '  yes  ' ELSE '  no   ' END || '{owner_id = authz.uid()}';
END $f$;

CREATE FUNCTION authz_gen."cx.files:insert:refuse"(p_row "cx"."files") RETURNS boolean
LANGUAGE plpgsql VOLATILE SET search_path FROM CURRENT AS $f$
DECLARE v_lines text; v_who text := CASE WHEN coalesce(current_setting('authz.user_id', true), '') = '' THEN 'someone not signed in'
  ELSE coalesce(nullif(current_setting('authz.principal_type', true), ''), 'user') || ' ' || current_setting('authz.user_id', true) END;
BEGIN
  BEGIN
    v_lines := (SELECT string_agg(l, E'\n') FROM authz_gen."cx.files:insert:why"(p_row) l);
  EXCEPTION WHEN OTHERS THEN
    v_lines := 'no explanation: ' || SQLERRM;
  END;
  RAISE EXCEPTION USING ERRCODE = 'insufficient_privilege', MESSAGE = 'permission denied: ' || v_who || ' may not ' || 'insert this row into cx.files',
    DETAIL = v_lines, SCHEMA = 'cx', TABLE = 'files', CONSTRAINT = 'authz_insert',
    HINT = 'rowstile help AZ709';
END $f$;

