CREATE FUNCTION authz_gen."cx.files:rules:explain"(p_command text, p_id text, p_row jsonb) RETURNS text[]
LANGUAGE plpgsql STABLE SET search_path FROM CURRENT AS $f$
DECLARE r_old "cx"."files"; r_new "cx"."files";
BEGIN
  IF p_command = 'insert' THEN
    RETURN ARRAY(SELECT * FROM authz_gen."cx.files:insert:why"(jsonb_populate_record(NULL::"cx"."files", coalesce(p_row, '{}'))));
  END IF;
  IF p_id IS NULL THEN
    RAISE EXCEPTION 'which row? authz.explain_rule(%, %, id)', 'cx.files', p_command USING ERRCODE = 'invalid_parameter_value', HINT = 'rowstile help AZ710';
  END IF;
  SELECT x.* INTO r_old FROM "cx"."files" x WHERE (x."org_id", x."id") = (((p_id)::authz_gen."file__key")."org_id", ((p_id)::authz_gen."file__key")."id");
  IF NOT FOUND THEN
    RETURN NULL;          -- not there, or the signed-in user can't see it
  END IF;
  IF p_command = 'delete' THEN
    RETURN ARRAY(SELECT * FROM authz_gen."cx.files:delete:why"(r_old));
  END IF;
  r_new := jsonb_populate_record(r_old, coalesce(p_row, '{}'));
  RETURN ARRAY(SELECT * FROM authz_gen."cx.files:update:why"(r_old)) || CASE WHEN p_row IS NULL THEN '{}'::text[] ELSE ARRAY['after the change:'] || ARRAY(SELECT '  ' || l FROM authz_gen."cx.files:update:why"(r_new) l) END;
END $f$;

