-- Foreign keys that delete governed rows skip row-level security
DO $fk$
DECLARE c record;
BEGIN
  FOR c IN SELECT con.conname, con.conrelid::regclass AS child, con.confrelid::regclass AS parent
           FROM pg_constraint con
           WHERE con.contype = 'f' AND con.confdeltype = 'c' AND con.conrelid IN ('"cx"."files"'::regclass, '"cx"."folders"'::regclass) LOOP
    RAISE WARNING 'foreign key % on % is ON DELETE CASCADE: deleting a row of % also deletes rows of %, and cascades skip row-level security, so a user could remove rows they cannot see. Use ON DELETE RESTRICT unless that is intended.',
      c.conname, c.child, c.parent, c.child;
  END LOOP;
END $fk$;

-- Column privileges: masked columns are read through the masked view only
DO $mc$
DECLARE r record; cols text;
BEGIN
  -- tables that are no longer masked get back the table-wide SELECT they had
  FOR r IN SELECT * FROM authz.masked_tables WHERE (tbl || '|' || role) <> ALL (ARRAY[]::text[]) LOOP
    IF to_regclass(r.tbl) IS NOT NULL AND EXISTS (SELECT 1 FROM pg_roles WHERE rolname = r.role) THEN
      EXECUTE format('GRANT SELECT ON %s TO %I', r.tbl, r.role);
    END IF;
    DELETE FROM authz.masked_tables WHERE tbl = r.tbl AND role = r.role;
  END LOOP;

END $mc$;

CREATE TABLE authz_int.masked_columns (tbl text, col text, view text, PRIMARY KEY (tbl, col));

-- Check a permission from app code: SELECT authz.can('file', 11, 'edit')
-- (only objects that exist; plans are cached per session)
CREATE OR REPLACE FUNCTION authz.can(p_type text, p_id text, p_perm text) RETURNS boolean
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
DECLARE v_allowed boolean; v_bigint bigint; v_text text;
BEGIN
  IF current_setting('authz_debug.log_decisions', true) = 'on'
     AND current_setting('authz_debug.logging', true) IS DISTINCT FROM 'on' THEN
    -- decision log (SET authz_debug.log_decisions = on; lines go to the server log)
    PERFORM set_config('authz_debug.logging', 'on', true);
    v_allowed := authz.can(p_type, p_id, p_perm);
    PERFORM set_config('authz_debug.logging', 'off', true);
    RAISE LOG 'authz decision: user=% type=% id=% perm=% -> %',
      coalesce(to_json(nullif(current_setting('authz.user_id', true), ''))::text, 'none'), to_json(p_type)::text,
      to_json(p_id)::text, to_json(p_perm)::text, coalesce(v_allowed::text, 'error');
    RETURN v_allowed;
  END IF;
  IF NOT authz_int.scope_perm(p_type, p_perm) THEN RETURN false; END IF;
  CASE p_type
    WHEN 'user' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'bigint') THEN RETURN false; END IF;
      v_bigint := p_id::bigint;
      CASE p_perm
        WHEN 'oversee' THEN RETURN EXISTS (SELECT 1 FROM "cx"."users" o WHERE o."id" = v_bigint AND ((coalesce(o."manager_id" = (SELECT authz.uid()), false)
    OR authz_gen."user__oversee__has"(o."manager_id"))));
        ELSE RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
      END CASE;
    WHEN 'bot' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'bigint') THEN RETURN false; END IF;
      v_bigint := p_id::bigint;
      CASE p_perm
        WHEN 'manage_keys' THEN RETURN EXISTS (SELECT 1 FROM "cx"."bots" o WHERE o."id" = v_bigint AND ((coalesce(o."owner_id" = (SELECT authz.uid()), false)
    AND coalesce((o.active), false))));
        ELSE RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
      END CASE;
    WHEN 'org' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'bigint') THEN RETURN false; END IF;
      v_bigint := p_id::bigint;
      RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
    WHEN 'team' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'authz_gen."team__key"') THEN RETURN false; END IF;
      v_text := p_id::authz_gen."team__key"::text;
      CASE p_perm
        WHEN 'share' THEN RETURN EXISTS (SELECT 1 FROM "cx"."teams" o WHERE (o."org_id", o."slug") = (((v_text)::authz_gen."team__key")."org_id", ((v_text)::authz_gen."team__key")."slug") AND ((coalesce(o."lead_id" = (SELECT authz.uid()), false)
    AND coalesce((not disbanded), false))));
        ELSE RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
      END CASE;
    WHEN 'project' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'authz_gen."project__key"') THEN RETURN false; END IF;
      v_text := p_id::authz_gen."project__key"::text;
      CASE p_perm
        WHEN 'edit' THEN RETURN EXISTS (SELECT 1 FROM "cx"."projects" o WHERE (o."org_id", o."id") = (((v_text)::authz_gen."project__key")."org_id", ((v_text)::authz_gen."project__key")."id") AND ((coalesce(o."lead_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_gen."org__admin" v WHERE v.id = o."org_id"))));
        WHEN 'view' THEN RETURN EXISTS (SELECT 1 FROM "cx"."projects" o WHERE (o."org_id", o."id") = (((v_text)::authz_gen."project__key")."org_id", ((v_text)::authz_gen."project__key")."id") AND ((coalesce(o."lead_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_gen."org__admin" v WHERE v.id = o."org_id")
    OR EXISTS (SELECT 1 FROM authz_gen."folder__view" v WHERE v.id = (CASE WHEN (o."org_id", o."folder_id") IS NOT NULL THEN ROW(o."org_id"::bigint, o."folder_id"::bigint)::text END)))));
        WHEN 'browse' THEN RETURN EXISTS (SELECT 1 FROM "cx"."projects" o WHERE (o."org_id", o."id") = (((v_text)::authz_gen."project__key")."org_id", ((v_text)::authz_gen."project__key")."id") AND ((coalesce(o."lead_id" = (SELECT authz.uid()), false)
    OR coalesce(((SELECT authz.uid()) IS NOT NULL), false)
    OR EXISTS (SELECT 1 FROM authz_gen."org__admin" v WHERE v.id = o."org_id")
    OR EXISTS (SELECT 1 FROM authz_gen."folder__view" v WHERE v.id = (CASE WHEN (o."org_id", o."folder_id") IS NOT NULL THEN ROW(o."org_id"::bigint, o."folder_id"::bigint)::text END)))));
        ELSE RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
      END CASE;
    WHEN 'folder' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'authz_gen."folder__key"') THEN RETURN false; END IF;
      v_text := p_id::authz_gen."folder__key"::text;
      CASE p_perm
        WHEN 'share' THEN RETURN EXISTS (SELECT 1 FROM "cx"."folders" o WHERE (o."org_id", o."id") = (((v_text)::authz_gen."folder__key")."org_id", ((v_text)::authz_gen."folder__key")."id") AND ((coalesce(o."owner_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_gen."org__admin" v WHERE v.id = o."org_id"))));
        WHEN 'edit' THEN RETURN EXISTS (SELECT 1 FROM "cx"."folders" o WHERE (o."org_id", o."id") = (((v_text)::authz_gen."folder__key")."org_id", ((v_text)::authz_gen."folder__key")."id") AND ((coalesce(o."owner_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_gen."org__admin" v WHERE v.id = o."org_id")
    OR EXISTS (SELECT 1 FROM authz_gen."folder__editor" v WHERE v.id = ROW(o."org_id"::bigint, o."id"::bigint)::text)
    OR ((o."parent_type" = 'folder' AND authz_gen."folder__edit__has"((CASE WHEN o."parent_type" = 'folder' THEN (CASE WHEN (o."org_id", o."parent_id") IS NOT NULL THEN ROW(o."org_id"::bigint, o."parent_id"::bigint)::text END) END)))
    OR (o."parent_type" = 'project' AND EXISTS (SELECT 1 FROM authz_gen."project__edit" v WHERE v.id = (CASE WHEN o."parent_type" = 'project' THEN (CASE WHEN (o."org_id", o."parent_id") IS NOT NULL THEN ROW(o."org_id"::bigint, o."parent_id"::bigint)::text END) END)))
    OR EXISTS (SELECT 1 FROM authz_gen."folder__parent__edit__ext" v WHERE v.id = ROW(o."org_id"::bigint, o."id"::bigint)::text)))));
        WHEN 'view' THEN RETURN EXISTS (SELECT 1 FROM "cx"."folders" o WHERE (o."org_id", o."id") = (((v_text)::authz_gen."folder__key")."org_id", ((v_text)::authz_gen."folder__key")."id") AND ((coalesce(o."owner_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_gen."org__admin" v WHERE v.id = o."org_id")
    OR EXISTS (SELECT 1 FROM authz_gen."folder__editor" v WHERE v.id = ROW(o."org_id"::bigint, o."id"::bigint)::text)
    OR EXISTS (SELECT 1 FROM authz_gen."folder__viewer" v WHERE v.id = ROW(o."org_id"::bigint, o."id"::bigint)::text)
    OR ((o."parent_type" = 'folder' AND EXISTS (SELECT 1 FROM authz_gen."folder__view" v WHERE v.id = (CASE WHEN o."parent_type" = 'folder' THEN (CASE WHEN (o."org_id", o."parent_id") IS NOT NULL THEN ROW(o."org_id"::bigint, o."parent_id"::bigint)::text END) END)))
    OR (o."parent_type" = 'project' AND EXISTS (SELECT 1 FROM authz_gen."project__view" v WHERE v.id = (CASE WHEN o."parent_type" = 'project' THEN (CASE WHEN (o."org_id", o."parent_id") IS NOT NULL THEN ROW(o."org_id"::bigint, o."parent_id"::bigint)::text END) END)))
    OR EXISTS (SELECT 1 FROM authz_gen."folder__parent__view__ext" v WHERE v.id = ROW(o."org_id"::bigint, o."id"::bigint)::text)))));
        ELSE RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
      END CASE;
    WHEN 'file' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'authz_gen."file__key"') THEN RETURN false; END IF;
      v_text := p_id::authz_gen."file__key"::text;
      CASE p_perm
        WHEN 'edit' THEN RETURN EXISTS (SELECT 1 FROM "cx"."files" o WHERE (o."org_id", o."id") = (((v_text)::authz_gen."file__key")."org_id", ((v_text)::authz_gen."file__key")."id") AND ((coalesce(o."owner_id" = (SELECT authz.uid()), false)
    OR coalesce(o."uploaded_by" = (SELECT authz_int."bot__me"()), false)
    OR authz_gen."folder__edit__has"((CASE WHEN (o."org_id", o."folder_id") IS NOT NULL THEN ROW(o."org_id"::bigint, o."folder_id"::bigint)::text END)))));
        WHEN 'view' THEN RETURN EXISTS (SELECT 1 FROM "cx"."files" o WHERE (o."org_id", o."id") = (((v_text)::authz_gen."file__key")."org_id", ((v_text)::authz_gen."file__key")."id") AND ((coalesce(o."owner_id" = (SELECT authz.uid()), false)
    OR coalesce(o."uploaded_by" = (SELECT authz_int."bot__me"()), false)
    OR EXISTS (SELECT 1 FROM authz_gen."folder__view" v WHERE v.id = (CASE WHEN (o."org_id", o."folder_id") IS NOT NULL THEN ROW(o."org_id"::bigint, o."folder_id"::bigint)::text END))
    OR authz_gen."user__oversee__has"(o."owner_id"))));
        ELSE RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
      END CASE;
    ELSE
      RAISE EXCEPTION 'no type % in the policy', p_type USING HINT = 'rowstile help AZ707';
  END CASE;
END $f$;

-- Everything the user holds a permission on: SELECT * FROM authz.list('folder', 'edit')
-- In pages, in key order: authz.list('file', 'view', NULL, 1000), then the last id seen as p_after
CREATE OR REPLACE FUNCTION authz.list(p_type text, p_perm text, p_after text DEFAULT NULL, p_limit int DEFAULT NULL)
RETURNS SETOF text
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
BEGIN
  -- a page cursor or size from a request: the caller's mistake, said plainly (the queries below would cast it)
  IF p_limit < 0 THEN
    RAISE EXCEPTION 'the page size must not be negative (got %)', p_limit
      USING ERRCODE = 'invalid_parameter_value', HINT = 'rowstile help AZ710';
  END IF;
  IF p_after IS NOT NULL AND NOT coalesce(pg_catalog.pg_input_is_valid(p_after,
                                            (SELECT keytype FROM authz_int.types WHERE name = p_type)), true) THEN
    RAISE EXCEPTION 'the page cursor % is not a % id', quote_literal(left(p_after, 40)), p_type
      USING ERRCODE = 'invalid_parameter_value', HINT = 'rowstile help AZ710';
  END IF;
  IF NOT authz_int.scope_perm(p_type, p_perm) THEN RETURN; END IF;
  CASE p_type || '.' || p_perm
    WHEN 'user.oversee' THEN
      IF p_limit IS NULL AND p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "cx"."users" o
        WHERE (coalesce(o."manager_id" = (SELECT authz.uid()), false)
    OR (EXISTS (SELECT 1 FROM authz_gen."user__oversee__direct" v WHERE v.id = o."manager_id")
    OR EXISTS (SELECT 1 FROM authz_gen."user__oversee" v WHERE v.id = o."manager_id")));
      ELSIF p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "cx"."users" o
        WHERE (coalesce(o."manager_id" = (SELECT authz.uid()), false)
    OR (EXISTS (SELECT 1 FROM authz_gen."user__oversee__direct" v WHERE v.id = o."manager_id")
    OR EXISTS (SELECT 1 FROM authz_gen."user__oversee" v WHERE v.id = o."manager_id")))
        ORDER BY o."id" LIMIT p_limit;
      ELSE
        RETURN QUERY SELECT o."id"::text FROM "cx"."users" o
        WHERE o."id" > p_after::bigint AND (coalesce(o."manager_id" = (SELECT authz.uid()), false)
    OR (EXISTS (SELECT 1 FROM authz_gen."user__oversee__direct" v WHERE v.id = o."manager_id")
    OR EXISTS (SELECT 1 FROM authz_gen."user__oversee" v WHERE v.id = o."manager_id")))
        ORDER BY o."id" LIMIT p_limit;
      END IF;
    WHEN 'bot.manage_keys' THEN
      IF p_limit IS NULL AND p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "cx"."bots" o
        WHERE (coalesce(o."owner_id" = (SELECT authz.uid()), false)
    AND coalesce((o.active), false));
      ELSIF p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "cx"."bots" o
        WHERE (coalesce(o."owner_id" = (SELECT authz.uid()), false)
    AND coalesce((o.active), false))
        ORDER BY o."id" LIMIT p_limit;
      ELSE
        RETURN QUERY SELECT o."id"::text FROM "cx"."bots" o
        WHERE o."id" > p_after::bigint AND (coalesce(o."owner_id" = (SELECT authz.uid()), false)
    AND coalesce((o.active), false))
        ORDER BY o."id" LIMIT p_limit;
      END IF;
    WHEN 'team.share' THEN
      IF p_limit IS NULL AND p_after IS NULL THEN
        RETURN QUERY SELECT ROW(o."org_id"::bigint, o."slug"::text)::text FROM "cx"."teams" o
        WHERE (coalesce(o."lead_id" = (SELECT authz.uid()), false)
    AND coalesce((not disbanded), false));
      ELSIF p_after IS NULL THEN
        RETURN QUERY SELECT ROW(o."org_id"::bigint, o."slug"::text)::text FROM "cx"."teams" o
        WHERE (coalesce(o."lead_id" = (SELECT authz.uid()), false)
    AND coalesce((not disbanded), false))
        ORDER BY o."org_id", o."slug" LIMIT p_limit;
      ELSE
        RETURN QUERY SELECT ROW(o."org_id"::bigint, o."slug"::text)::text FROM "cx"."teams" o
        WHERE (o."org_id", o."slug") > ((p_after::authz_gen."team__key")."org_id", (p_after::authz_gen."team__key")."slug") AND (coalesce(o."lead_id" = (SELECT authz.uid()), false)
    AND coalesce((not disbanded), false))
        ORDER BY o."org_id", o."slug" LIMIT p_limit;
      END IF;
    WHEN 'project.edit' THEN
      IF p_limit IS NULL AND p_after IS NULL THEN
        RETURN QUERY SELECT ROW(o."org_id"::bigint, o."id"::bigint)::text FROM "cx"."projects" o
        WHERE (coalesce(o."lead_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_gen."org__admin" v WHERE v.id = o."org_id"));
      ELSIF p_after IS NULL THEN
        RETURN QUERY SELECT ROW(o."org_id"::bigint, o."id"::bigint)::text FROM "cx"."projects" o
        WHERE (coalesce(o."lead_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_gen."org__admin" v WHERE v.id = o."org_id"))
        ORDER BY o."org_id", o."id" LIMIT p_limit;
      ELSE
        RETURN QUERY SELECT ROW(o."org_id"::bigint, o."id"::bigint)::text FROM "cx"."projects" o
        WHERE (o."org_id", o."id") > ((p_after::authz_gen."project__key")."org_id", (p_after::authz_gen."project__key")."id") AND (coalesce(o."lead_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_gen."org__admin" v WHERE v.id = o."org_id"))
        ORDER BY o."org_id", o."id" LIMIT p_limit;
      END IF;
    WHEN 'project.view' THEN
      IF p_limit IS NULL AND p_after IS NULL THEN
        RETURN QUERY SELECT ROW(o."org_id"::bigint, o."id"::bigint)::text FROM "cx"."projects" o
        WHERE (coalesce(o."lead_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_gen."org__admin" v WHERE v.id = o."org_id")
    OR EXISTS (SELECT 1 FROM authz_gen."folder__view" v WHERE v.id = (CASE WHEN (o."org_id", o."folder_id") IS NOT NULL THEN ROW(o."org_id"::bigint, o."folder_id"::bigint)::text END)));
      ELSIF p_after IS NULL THEN
        RETURN QUERY SELECT ROW(o."org_id"::bigint, o."id"::bigint)::text FROM "cx"."projects" o
        WHERE (coalesce(o."lead_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_gen."org__admin" v WHERE v.id = o."org_id")
    OR EXISTS (SELECT 1 FROM authz_gen."folder__view" v WHERE v.id = (CASE WHEN (o."org_id", o."folder_id") IS NOT NULL THEN ROW(o."org_id"::bigint, o."folder_id"::bigint)::text END)))
        ORDER BY o."org_id", o."id" LIMIT p_limit;
      ELSE
        RETURN QUERY SELECT ROW(o."org_id"::bigint, o."id"::bigint)::text FROM "cx"."projects" o
        WHERE (o."org_id", o."id") > ((p_after::authz_gen."project__key")."org_id", (p_after::authz_gen."project__key")."id") AND (coalesce(o."lead_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_gen."org__admin" v WHERE v.id = o."org_id")
    OR EXISTS (SELECT 1 FROM authz_gen."folder__view" v WHERE v.id = (CASE WHEN (o."org_id", o."folder_id") IS NOT NULL THEN ROW(o."org_id"::bigint, o."folder_id"::bigint)::text END)))
        ORDER BY o."org_id", o."id" LIMIT p_limit;
      END IF;
    WHEN 'project.browse' THEN
      IF p_limit IS NULL AND p_after IS NULL THEN
        RETURN QUERY SELECT ROW(o."org_id"::bigint, o."id"::bigint)::text FROM "cx"."projects" o
        WHERE (coalesce(o."lead_id" = (SELECT authz.uid()), false)
    OR coalesce(((SELECT authz.uid()) IS NOT NULL), false)
    OR EXISTS (SELECT 1 FROM authz_gen."org__admin" v WHERE v.id = o."org_id")
    OR EXISTS (SELECT 1 FROM authz_gen."folder__view" v WHERE v.id = (CASE WHEN (o."org_id", o."folder_id") IS NOT NULL THEN ROW(o."org_id"::bigint, o."folder_id"::bigint)::text END)));
      ELSIF p_after IS NULL THEN
        RETURN QUERY SELECT ROW(o."org_id"::bigint, o."id"::bigint)::text FROM "cx"."projects" o
        WHERE (coalesce(o."lead_id" = (SELECT authz.uid()), false)
    OR coalesce(((SELECT authz.uid()) IS NOT NULL), false)
    OR EXISTS (SELECT 1 FROM authz_gen."org__admin" v WHERE v.id = o."org_id")
    OR EXISTS (SELECT 1 FROM authz_gen."folder__view" v WHERE v.id = (CASE WHEN (o."org_id", o."folder_id") IS NOT NULL THEN ROW(o."org_id"::bigint, o."folder_id"::bigint)::text END)))
        ORDER BY o."org_id", o."id" LIMIT p_limit;
      ELSE
        RETURN QUERY SELECT ROW(o."org_id"::bigint, o."id"::bigint)::text FROM "cx"."projects" o
        WHERE (o."org_id", o."id") > ((p_after::authz_gen."project__key")."org_id", (p_after::authz_gen."project__key")."id") AND (coalesce(o."lead_id" = (SELECT authz.uid()), false)
    OR coalesce(((SELECT authz.uid()) IS NOT NULL), false)
    OR EXISTS (SELECT 1 FROM authz_gen."org__admin" v WHERE v.id = o."org_id")
    OR EXISTS (SELECT 1 FROM authz_gen."folder__view" v WHERE v.id = (CASE WHEN (o."org_id", o."folder_id") IS NOT NULL THEN ROW(o."org_id"::bigint, o."folder_id"::bigint)::text END)))
        ORDER BY o."org_id", o."id" LIMIT p_limit;
      END IF;
    WHEN 'folder.share' THEN
      IF p_limit IS NULL AND p_after IS NULL THEN
        RETURN QUERY SELECT ROW(o."org_id"::bigint, o."id"::bigint)::text FROM "cx"."folders" o
        WHERE (coalesce(o."owner_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_gen."org__admin" v WHERE v.id = o."org_id"));
      ELSIF p_after IS NULL THEN
        RETURN QUERY SELECT ROW(o."org_id"::bigint, o."id"::bigint)::text FROM "cx"."folders" o
        WHERE (coalesce(o."owner_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_gen."org__admin" v WHERE v.id = o."org_id"))
        ORDER BY o."org_id", o."id" LIMIT p_limit;
      ELSE
        RETURN QUERY SELECT ROW(o."org_id"::bigint, o."id"::bigint)::text FROM "cx"."folders" o
        WHERE (o."org_id", o."id") > ((p_after::authz_gen."folder__key")."org_id", (p_after::authz_gen."folder__key")."id") AND (coalesce(o."owner_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_gen."org__admin" v WHERE v.id = o."org_id"))
        ORDER BY o."org_id", o."id" LIMIT p_limit;
      END IF;
    WHEN 'folder.edit' THEN
      IF p_limit IS NULL AND p_after IS NULL THEN
        RETURN QUERY SELECT ROW(o."org_id"::bigint, o."id"::bigint)::text FROM "cx"."folders" o
        WHERE (coalesce(o."owner_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_gen."org__admin" v WHERE v.id = o."org_id")
    OR EXISTS (SELECT 1 FROM authz_gen."folder__editor" v WHERE v.id = ROW(o."org_id"::bigint, o."id"::bigint)::text)
    OR ((o."parent_type" = 'folder' AND EXISTS (SELECT 1 FROM authz_gen."folder__edit" v WHERE v.id = (CASE WHEN o."parent_type" = 'folder' THEN (CASE WHEN (o."org_id", o."parent_id") IS NOT NULL THEN ROW(o."org_id"::bigint, o."parent_id"::bigint)::text END) END)))
    OR (o."parent_type" = 'project' AND EXISTS (SELECT 1 FROM authz_gen."project__edit" v WHERE v.id = (CASE WHEN o."parent_type" = 'project' THEN (CASE WHEN (o."org_id", o."parent_id") IS NOT NULL THEN ROW(o."org_id"::bigint, o."parent_id"::bigint)::text END) END)))
    OR EXISTS (SELECT 1 FROM authz_gen."folder__parent__edit__ext" v WHERE v.id = ROW(o."org_id"::bigint, o."id"::bigint)::text)));
      ELSIF p_after IS NULL THEN
        RETURN QUERY SELECT ROW(o."org_id"::bigint, o."id"::bigint)::text FROM "cx"."folders" o
        WHERE (coalesce(o."owner_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_gen."org__admin" v WHERE v.id = o."org_id")
    OR EXISTS (SELECT 1 FROM authz_gen."folder__editor" v WHERE v.id = ROW(o."org_id"::bigint, o."id"::bigint)::text)
    OR ((o."parent_type" = 'folder' AND EXISTS (SELECT 1 FROM authz_gen."folder__edit" v WHERE v.id = (CASE WHEN o."parent_type" = 'folder' THEN (CASE WHEN (o."org_id", o."parent_id") IS NOT NULL THEN ROW(o."org_id"::bigint, o."parent_id"::bigint)::text END) END)))
    OR (o."parent_type" = 'project' AND EXISTS (SELECT 1 FROM authz_gen."project__edit" v WHERE v.id = (CASE WHEN o."parent_type" = 'project' THEN (CASE WHEN (o."org_id", o."parent_id") IS NOT NULL THEN ROW(o."org_id"::bigint, o."parent_id"::bigint)::text END) END)))
    OR EXISTS (SELECT 1 FROM authz_gen."folder__parent__edit__ext" v WHERE v.id = ROW(o."org_id"::bigint, o."id"::bigint)::text)))
        ORDER BY o."org_id", o."id" LIMIT p_limit;
      ELSE
        RETURN QUERY SELECT ROW(o."org_id"::bigint, o."id"::bigint)::text FROM "cx"."folders" o
        WHERE (o."org_id", o."id") > ((p_after::authz_gen."folder__key")."org_id", (p_after::authz_gen."folder__key")."id") AND (coalesce(o."owner_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_gen."org__admin" v WHERE v.id = o."org_id")
    OR EXISTS (SELECT 1 FROM authz_gen."folder__editor" v WHERE v.id = ROW(o."org_id"::bigint, o."id"::bigint)::text)
    OR ((o."parent_type" = 'folder' AND EXISTS (SELECT 1 FROM authz_gen."folder__edit" v WHERE v.id = (CASE WHEN o."parent_type" = 'folder' THEN (CASE WHEN (o."org_id", o."parent_id") IS NOT NULL THEN ROW(o."org_id"::bigint, o."parent_id"::bigint)::text END) END)))
    OR (o."parent_type" = 'project' AND EXISTS (SELECT 1 FROM authz_gen."project__edit" v WHERE v.id = (CASE WHEN o."parent_type" = 'project' THEN (CASE WHEN (o."org_id", o."parent_id") IS NOT NULL THEN ROW(o."org_id"::bigint, o."parent_id"::bigint)::text END) END)))
    OR EXISTS (SELECT 1 FROM authz_gen."folder__parent__edit__ext" v WHERE v.id = ROW(o."org_id"::bigint, o."id"::bigint)::text)))
        ORDER BY o."org_id", o."id" LIMIT p_limit;
      END IF;
    WHEN 'folder.view' THEN
      IF p_limit IS NULL AND p_after IS NULL THEN
        RETURN QUERY SELECT ROW(o."org_id"::bigint, o."id"::bigint)::text FROM "cx"."folders" o
        WHERE (coalesce(o."owner_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_gen."org__admin" v WHERE v.id = o."org_id")
    OR EXISTS (SELECT 1 FROM authz_gen."folder__editor" v WHERE v.id = ROW(o."org_id"::bigint, o."id"::bigint)::text)
    OR EXISTS (SELECT 1 FROM authz_gen."folder__viewer" v WHERE v.id = ROW(o."org_id"::bigint, o."id"::bigint)::text)
    OR ((o."parent_type" = 'folder' AND EXISTS (SELECT 1 FROM authz_gen."folder__view" v WHERE v.id = (CASE WHEN o."parent_type" = 'folder' THEN (CASE WHEN (o."org_id", o."parent_id") IS NOT NULL THEN ROW(o."org_id"::bigint, o."parent_id"::bigint)::text END) END)))
    OR (o."parent_type" = 'project' AND EXISTS (SELECT 1 FROM authz_gen."project__view" v WHERE v.id = (CASE WHEN o."parent_type" = 'project' THEN (CASE WHEN (o."org_id", o."parent_id") IS NOT NULL THEN ROW(o."org_id"::bigint, o."parent_id"::bigint)::text END) END)))
    OR EXISTS (SELECT 1 FROM authz_gen."folder__parent__view__ext" v WHERE v.id = ROW(o."org_id"::bigint, o."id"::bigint)::text)));
      ELSIF p_after IS NULL THEN
        RETURN QUERY SELECT ROW(o."org_id"::bigint, o."id"::bigint)::text FROM "cx"."folders" o
        WHERE (coalesce(o."owner_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_gen."org__admin" v WHERE v.id = o."org_id")
    OR EXISTS (SELECT 1 FROM authz_gen."folder__editor" v WHERE v.id = ROW(o."org_id"::bigint, o."id"::bigint)::text)
    OR EXISTS (SELECT 1 FROM authz_gen."folder__viewer" v WHERE v.id = ROW(o."org_id"::bigint, o."id"::bigint)::text)
    OR ((o."parent_type" = 'folder' AND EXISTS (SELECT 1 FROM authz_gen."folder__view" v WHERE v.id = (CASE WHEN o."parent_type" = 'folder' THEN (CASE WHEN (o."org_id", o."parent_id") IS NOT NULL THEN ROW(o."org_id"::bigint, o."parent_id"::bigint)::text END) END)))
    OR (o."parent_type" = 'project' AND EXISTS (SELECT 1 FROM authz_gen."project__view" v WHERE v.id = (CASE WHEN o."parent_type" = 'project' THEN (CASE WHEN (o."org_id", o."parent_id") IS NOT NULL THEN ROW(o."org_id"::bigint, o."parent_id"::bigint)::text END) END)))
    OR EXISTS (SELECT 1 FROM authz_gen."folder__parent__view__ext" v WHERE v.id = ROW(o."org_id"::bigint, o."id"::bigint)::text)))
        ORDER BY o."org_id", o."id" LIMIT p_limit;
      ELSE
        RETURN QUERY SELECT ROW(o."org_id"::bigint, o."id"::bigint)::text FROM "cx"."folders" o
        WHERE (o."org_id", o."id") > ((p_after::authz_gen."folder__key")."org_id", (p_after::authz_gen."folder__key")."id") AND (coalesce(o."owner_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_gen."org__admin" v WHERE v.id = o."org_id")
    OR EXISTS (SELECT 1 FROM authz_gen."folder__editor" v WHERE v.id = ROW(o."org_id"::bigint, o."id"::bigint)::text)
    OR EXISTS (SELECT 1 FROM authz_gen."folder__viewer" v WHERE v.id = ROW(o."org_id"::bigint, o."id"::bigint)::text)
    OR ((o."parent_type" = 'folder' AND EXISTS (SELECT 1 FROM authz_gen."folder__view" v WHERE v.id = (CASE WHEN o."parent_type" = 'folder' THEN (CASE WHEN (o."org_id", o."parent_id") IS NOT NULL THEN ROW(o."org_id"::bigint, o."parent_id"::bigint)::text END) END)))
    OR (o."parent_type" = 'project' AND EXISTS (SELECT 1 FROM authz_gen."project__view" v WHERE v.id = (CASE WHEN o."parent_type" = 'project' THEN (CASE WHEN (o."org_id", o."parent_id") IS NOT NULL THEN ROW(o."org_id"::bigint, o."parent_id"::bigint)::text END) END)))
    OR EXISTS (SELECT 1 FROM authz_gen."folder__parent__view__ext" v WHERE v.id = ROW(o."org_id"::bigint, o."id"::bigint)::text)))
        ORDER BY o."org_id", o."id" LIMIT p_limit;
      END IF;
    WHEN 'file.edit' THEN
      IF p_limit IS NULL AND p_after IS NULL THEN
        RETURN QUERY SELECT ROW(o."org_id"::bigint, o."id"::bigint)::text FROM "cx"."files" o
        WHERE (coalesce(o."owner_id" = (SELECT authz.uid()), false)
    OR coalesce(o."uploaded_by" = (SELECT authz_int."bot__me"()), false)
    OR EXISTS (SELECT 1 FROM authz_gen."folder__edit" v WHERE v.id = (CASE WHEN (o."org_id", o."folder_id") IS NOT NULL THEN ROW(o."org_id"::bigint, o."folder_id"::bigint)::text END)));
      ELSIF p_after IS NULL THEN
        RETURN QUERY SELECT ROW(o."org_id"::bigint, o."id"::bigint)::text FROM "cx"."files" o
        WHERE (coalesce(o."owner_id" = (SELECT authz.uid()), false)
    OR coalesce(o."uploaded_by" = (SELECT authz_int."bot__me"()), false)
    OR EXISTS (SELECT 1 FROM authz_gen."folder__edit" v WHERE v.id = (CASE WHEN (o."org_id", o."folder_id") IS NOT NULL THEN ROW(o."org_id"::bigint, o."folder_id"::bigint)::text END)))
        ORDER BY o."org_id", o."id" LIMIT p_limit;
      ELSE
        RETURN QUERY SELECT ROW(o."org_id"::bigint, o."id"::bigint)::text FROM "cx"."files" o
        WHERE (o."org_id", o."id") > ((p_after::authz_gen."file__key")."org_id", (p_after::authz_gen."file__key")."id") AND (coalesce(o."owner_id" = (SELECT authz.uid()), false)
    OR coalesce(o."uploaded_by" = (SELECT authz_int."bot__me"()), false)
    OR EXISTS (SELECT 1 FROM authz_gen."folder__edit" v WHERE v.id = (CASE WHEN (o."org_id", o."folder_id") IS NOT NULL THEN ROW(o."org_id"::bigint, o."folder_id"::bigint)::text END)))
        ORDER BY o."org_id", o."id" LIMIT p_limit;
      END IF;
    WHEN 'file.view' THEN
      IF p_limit IS NULL AND p_after IS NULL THEN
        RETURN QUERY SELECT ROW(o."org_id"::bigint, o."id"::bigint)::text FROM "cx"."files" o
        WHERE (coalesce(o."owner_id" = (SELECT authz.uid()), false)
    OR coalesce(o."uploaded_by" = (SELECT authz_int."bot__me"()), false)
    OR EXISTS (SELECT 1 FROM authz_gen."folder__view" v WHERE v.id = (CASE WHEN (o."org_id", o."folder_id") IS NOT NULL THEN ROW(o."org_id"::bigint, o."folder_id"::bigint)::text END))
    OR (EXISTS (SELECT 1 FROM authz_gen."user__oversee__direct" v WHERE v.id = o."owner_id")
    OR EXISTS (SELECT 1 FROM authz_gen."user__oversee" v WHERE v.id = o."owner_id")));
      ELSIF p_after IS NULL THEN
        RETURN QUERY SELECT ROW(o."org_id"::bigint, o."id"::bigint)::text FROM "cx"."files" o
        WHERE (coalesce(o."owner_id" = (SELECT authz.uid()), false)
    OR coalesce(o."uploaded_by" = (SELECT authz_int."bot__me"()), false)
    OR EXISTS (SELECT 1 FROM authz_gen."folder__view" v WHERE v.id = (CASE WHEN (o."org_id", o."folder_id") IS NOT NULL THEN ROW(o."org_id"::bigint, o."folder_id"::bigint)::text END))
    OR (EXISTS (SELECT 1 FROM authz_gen."user__oversee__direct" v WHERE v.id = o."owner_id")
    OR EXISTS (SELECT 1 FROM authz_gen."user__oversee" v WHERE v.id = o."owner_id")))
        ORDER BY o."org_id", o."id" LIMIT p_limit;
      ELSE
        RETURN QUERY SELECT ROW(o."org_id"::bigint, o."id"::bigint)::text FROM "cx"."files" o
        WHERE (o."org_id", o."id") > ((p_after::authz_gen."file__key")."org_id", (p_after::authz_gen."file__key")."id") AND (coalesce(o."owner_id" = (SELECT authz.uid()), false)
    OR coalesce(o."uploaded_by" = (SELECT authz_int."bot__me"()), false)
    OR EXISTS (SELECT 1 FROM authz_gen."folder__view" v WHERE v.id = (CASE WHEN (o."org_id", o."folder_id") IS NOT NULL THEN ROW(o."org_id"::bigint, o."folder_id"::bigint)::text END))
    OR (EXISTS (SELECT 1 FROM authz_gen."user__oversee__direct" v WHERE v.id = o."owner_id")
    OR EXISTS (SELECT 1 FROM authz_gen."user__oversee" v WHERE v.id = o."owner_id")))
        ORDER BY o."org_id", o."id" LIMIT p_limit;
      END IF;
    ELSE
      RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
  END CASE;
END $f$;

-- Every permission the user holds on one object: SELECT authz.perms('file', 11)
CREATE OR REPLACE FUNCTION authz.perms(p_type text, p_id text) RETURNS text[]
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE names text[];
BEGIN
  CASE p_type
    WHEN 'user' THEN names := ARRAY['oversee']::text[];
    WHEN 'bot' THEN names := ARRAY['manage_keys']::text[];
    WHEN 'org' THEN names := ARRAY[]::text[];
    WHEN 'team' THEN names := ARRAY['share']::text[];
    WHEN 'project' THEN names := ARRAY['edit', 'view', 'browse']::text[];
    WHEN 'folder' THEN names := ARRAY['share', 'edit', 'view']::text[];
    WHEN 'file' THEN names := ARRAY['edit', 'view']::text[];
    ELSE RAISE EXCEPTION 'no type % in the policy', p_type USING HINT = 'rowstile help AZ707';
  END CASE;
  RETURN ARRAY(SELECT n FROM unnest(names) n WHERE authz.can(p_type, p_id, n));
END $f$;

-- The permissions the user holds on many objects, in one call (a list's buttons): SELECT * FROM authz.perms_of('folder', ARRAY['1', '2'])
CREATE OR REPLACE FUNCTION authz.perms_of(p_type text, p_ids text[]) RETURNS TABLE (id text, perms text[])
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
BEGIN
  RETURN QUERY SELECT x, authz.perms(p_type, x) FROM unnest(p_ids) WITH ORDINALITY u(x, n) ORDER BY n;
END $f$;
CREATE OR REPLACE FUNCTION authz.can(p_type text, p_id bigint, p_perm text) RETURNS boolean LANGUAGE sql STABLE AS
  $$ SELECT authz.can(p_type, p_id::text, p_perm) $$;
CREATE OR REPLACE FUNCTION authz.perms(p_type text, p_id bigint) RETURNS text[] LANGUAGE sql STABLE AS
  $$ SELECT authz.perms(p_type, p_id::text) $$;

-- Share: needs the relation's 'shared by' permission on the object, and every permission
-- the relation grants (you can't grant more than you hold); the subject must exist
CREATE OR REPLACE FUNCTION authz.share(p_type text, p_id text, p_relation text,
  p_subject_type text, p_subject_id text, p_subject_relation text DEFAULT '',
  p_expires_at timestamptz DEFAULT NULL, p_starts_at timestamptz DEFAULT NULL,
  p_caveat text DEFAULT NULL, p_caveat_args jsonb DEFAULT NULL) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE v_tbl text; v_find text; v_found boolean; v_key text; v_rel authz_int.shared_relations; v_need text;
        v_role authz.roles;
BEGIN
  PERFORM authz_int.check_writable();
  p_id := authz_int.canon(p_type, p_id);
  p_subject_id := authz_int.canon(p_subject_type, p_subject_id);
  IF NOT EXISTS (SELECT 1 FROM authz.principal()) THEN
    RAISE EXCEPTION 'you cannot share % %', p_type, p_id USING ERRCODE = 'insufficient_privilege', HINT = 'rowstile help AZ705';
  END IF;
  -- lock the object (FOR KEY SHARE): a concurrent delete waits for us, or we for it
  SELECT t.tbl, t.find INTO v_tbl, v_find FROM authz_int.types t WHERE t.name = p_type;
  IF v_tbl IS NULL THEN RAISE EXCEPTION 'no type % in the policy', p_type USING HINT = 'rowstile help AZ707'; END IF;
  IF NOT pg_catalog.pg_input_is_valid(p_id, (SELECT keytype FROM authz_int.types WHERE name = p_type)) THEN
    RAISE EXCEPTION 'you cannot share % %', p_type, p_id USING ERRCODE = 'insufficient_privilege', HINT = 'rowstile help AZ705';
  END IF;
  EXECUTE format('SELECT EXISTS (SELECT 1 FROM %s x WHERE %s FOR KEY SHARE)', v_tbl, v_find) INTO v_found USING p_id;
  -- a caller who may share nothing on the object gets the answer a missing object gets (this same RAISE),
  -- before the subject and the relation are looked at: sharing never tells a hidden object from a missing one
  v_found := v_found AND EXISTS (
    SELECT 1 FROM (SELECT s.shared_by AS perm FROM authz_int.shared_relations s WHERE s.object_type = p_type
                   UNION SELECT 'share') x
    -- (CASE: authz.can raises for a permission the type doesn't have, and AND doesn't say which runs first)
    WHERE CASE WHEN EXISTS (SELECT 1 FROM authz_int.perms WHERE type = p_type AND perm = x.perm)
               THEN authz.can(p_type, p_id, x.perm) ELSE false END);
  IF NOT v_found THEN
    RAISE EXCEPTION 'you cannot share % %', p_type, p_id USING ERRCODE = 'insufficient_privilege', HINT = 'rowstile help AZ705';
  END IF;
  v_key := CASE WHEN p_subject_type IN ('anyone', 'link') THEN p_subject_type
                WHEN p_subject_id = '*' AND p_subject_relation = '' THEN p_subject_type || ':*'
                WHEN p_subject_relation <> '' THEN p_subject_type || '#' || p_subject_relation
                ELSE p_subject_type END;
  -- the subject must exist (and is locked, like the object)
  IF v_key NOT LIKE '%:*' AND v_key NOT IN ('anyone', 'link') THEN
    SELECT t.tbl, t.find INTO v_tbl, v_find FROM authz_int.types t WHERE t.name = p_subject_type;
    v_found := v_tbl IS NOT NULL AND pg_catalog.pg_input_is_valid(p_subject_id,
                 (SELECT keytype FROM authz_int.types WHERE name = p_subject_type));
    IF v_found THEN
      EXECUTE format('SELECT EXISTS (SELECT 1 FROM %s x WHERE %s FOR KEY SHARE)', v_tbl, v_find)
        INTO v_found USING p_subject_id;
    END IF;
    IF NOT v_found THEN
      RAISE EXCEPTION 'there is no % %', p_subject_type, p_subject_id USING HINT = 'rowstile help AZ708';
    END IF;
  END IF;
  IF p_relation LIKE 'role:%' THEN
    -- a custom role: its type must match, the subject must be allowed, and you must hold all it grants
    SELECT * INTO v_role FROM authz.roles WHERE 'role:' || id = p_relation;
    IF v_role.id IS NULL OR v_role.object_type <> p_type THEN
      RAISE EXCEPTION 'no role % for %', p_relation, p_type USING HINT = 'rowstile help AZ706';
    END IF;
    IF NOT authz_int.role_owned(p_type, p_id, v_role.owner_type, v_role.owner_id) THEN
      RAISE EXCEPTION 'role % belongs to % %, which doesn''t own % %', v_role.name, v_role.owner_type, v_role.owner_id,
        p_type, p_id USING HINT = 'rowstile help AZ706';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM authz_int.role_subjects WHERE object_type = p_type AND subject = v_key) THEN
      RAISE EXCEPTION 'custom roles on % cannot be given to %', p_type, v_key USING HINT = 'rowstile help AZ706';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM authz_int.perms WHERE type = p_type AND perm = 'share')
       OR NOT authz.can(p_type, p_id, 'share') THEN
      RAISE EXCEPTION 'you cannot share % %', p_type, p_id USING ERRCODE = 'insufficient_privilege', HINT = 'rowstile help AZ705';
    END IF;
    SELECT string_agg(permission, ', ') INTO v_need FROM authz.role_permissions
    WHERE role_id = v_role.id AND NOT authz.can(p_type, p_id, permission);
    IF v_need IS NOT NULL THEN
      RAISE EXCEPTION 'you cannot give role % on % %: you do not hold %', v_role.name, p_type, p_id, v_need
        USING ERRCODE = 'insufficient_privilege', HINT = 'rowstile help AZ705';
    END IF;
  ELSE
    SELECT * INTO v_rel FROM authz_int.shared_relations s
    WHERE s.object_type = p_type AND s.relation = p_relation AND s.subject = v_key;
    IF v_rel.relation IS NULL THEN
      RAISE EXCEPTION 'the policy does not allow sharing %.% with %', p_type, p_relation, v_key USING HINT = 'rowstile help AZ706';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM authz_int.perms WHERE type = p_type AND perm = v_rel.shared_by)
       OR NOT authz.can(p_type, p_id, v_rel.shared_by) THEN
      RAISE EXCEPTION 'you cannot share % % (needs %)', p_type, p_id, v_rel.shared_by USING ERRCODE = 'insufficient_privilege', HINT = 'rowstile help AZ705';
    END IF;
    SELECT string_agg(n, ', ') INTO v_need FROM unnest(v_rel.required) n WHERE NOT authz.can(p_type, p_id, n);
    IF v_need IS NOT NULL THEN
      RAISE EXCEPTION 'you cannot grant %.% on % %: you do not hold %', p_type, p_relation, p_type, p_id, v_need
        USING ERRCODE = 'insufficient_privilege', HINT = 'rowstile help AZ705';
    END IF;
    IF NOT authz_int.share_if(p_type || '.' || p_relation || '.' || v_key, p_id, p_subject_type,
                              p_subject_id, p_subject_relation) THEN
      RAISE EXCEPTION 'the policy does not allow this share (%)', coalesce((SELECT l.loc FROM authz_gen.policy_lines l WHERE l.what = v_rel.loc), '?') USING ERRCODE = 'insufficient_privilege', HINT = 'rowstile help AZ705';
    END IF;
  END IF;
  IF p_caveat IS NOT NULL AND NOT EXISTS (SELECT 1 FROM authz_int.caveats WHERE name = p_caveat) THEN
    RAISE EXCEPTION 'no caveat % in the policy', p_caveat USING HINT = 'rowstile help AZ707';
  END IF;
  PERFORM authz_int.mark_row(p_type, p_id);
  IF v_key NOT LIKE '%:*' AND v_key NOT IN ('anyone', 'link') THEN
    PERFORM authz_int.mark_row(p_subject_type, p_subject_id);
  END IF;
  INSERT INTO authz.shares (object_type, object_id, relation, subject_type, subject_id, subject_relation,
                            expires_at, created_by, starts_at, caveat, caveat_args)
  VALUES (p_type, p_id, p_relation, p_subject_type, p_subject_id, p_subject_relation,
          p_expires_at, authz_int.actor(), p_starts_at, p_caveat, p_caveat_args)
  ON CONFLICT ON CONSTRAINT shares_pkey
  DO UPDATE SET expires_at = EXCLUDED.expires_at, created_by = EXCLUDED.created_by,
                starts_at = EXCLUDED.starts_at, caveat = EXCLUDED.caveat, caveat_args = EXCLUDED.caveat_args;
END $f$;
CREATE OR REPLACE FUNCTION authz.share(p_type text, p_id bigint, p_relation text, p_subject_type text, p_subject_id bigint,
  p_subject_relation text DEFAULT '', p_expires_at timestamptz DEFAULT NULL, p_starts_at timestamptz DEFAULT NULL,
  p_caveat text DEFAULT NULL, p_caveat_args jsonb DEFAULT NULL) RETURNS void LANGUAGE sql AS
  $$ SELECT authz.share(p_type, p_id::text, p_relation, p_subject_type, p_subject_id::text, p_subject_relation,
                        p_expires_at, p_starts_at, p_caveat, p_caveat_args) $$;
CREATE OR REPLACE FUNCTION authz.share(p_type text, p_id bigint, p_relation text, p_subject_type text, p_subject_id text,
  p_subject_relation text DEFAULT '', p_expires_at timestamptz DEFAULT NULL, p_starts_at timestamptz DEFAULT NULL,
  p_caveat text DEFAULT NULL, p_caveat_args jsonb DEFAULT NULL) RETURNS void LANGUAGE sql AS
  $$ SELECT authz.share(p_type, p_id::text, p_relation, p_subject_type, p_subject_id, p_subject_relation,
                        p_expires_at, p_starts_at, p_caveat, p_caveat_args) $$;

-- Unshare: needs what sharing needs (the relation's 'shared by' permission)
CREATE OR REPLACE FUNCTION authz.unshare(p_type text, p_id text, p_relation text,
  p_subject_type text, p_subject_id text, p_subject_relation text DEFAULT '') RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE v_by text;
BEGIN
  PERFORM authz_int.check_writable();
  p_id := authz_int.canon(p_type, p_id);
  p_subject_id := authz_int.canon(p_subject_type, p_subject_id);
  v_by := coalesce(authz_int.manage_perm(p_type, p_relation,
                                         authz_int.subject_key(p_subject_type, p_subject_id, p_subject_relation)),
                   authz_int.manage_perm(p_type, p_relation));
  -- what it needs comes from the policy alone: the same words for a hidden object and a missing one
  IF NOT EXISTS (SELECT 1 FROM authz.principal()) OR v_by IS NULL
     OR NOT EXISTS (SELECT 1 FROM authz_int.perms WHERE type = p_type AND perm = v_by)
     OR NOT authz.can(p_type, p_id, v_by) THEN
    IF v_by IS NULL THEN
      RAISE EXCEPTION 'you cannot unshare % on % %', p_relation, p_type, p_id USING ERRCODE = 'insufficient_privilege', HINT = 'rowstile help AZ705';
    END IF;
    RAISE EXCEPTION 'you cannot unshare % on % % (needs %)', p_relation, p_type, p_id, v_by USING ERRCODE = 'insufficient_privilege', HINT = 'rowstile help AZ705';
  END IF;
  DELETE FROM authz.shares WHERE object_type = p_type AND object_id = p_id
    AND relation = p_relation AND subject_type = p_subject_type
    AND subject_id = p_subject_id AND subject_relation = p_subject_relation;
END $f$;
CREATE OR REPLACE FUNCTION authz.unshare(p_type text, p_id bigint, p_relation text, p_subject_type text, p_subject_id bigint,
  p_subject_relation text DEFAULT '') RETURNS void LANGUAGE sql AS
  $$ SELECT authz.unshare(p_type, p_id::text, p_relation, p_subject_type, p_subject_id::text, p_subject_relation) $$;
CREATE OR REPLACE FUNCTION authz.unshare(p_type text, p_id bigint, p_relation text, p_subject_type text, p_subject_id text,
  p_subject_relation text DEFAULT '') RETURNS void LANGUAGE sql AS
  $$ SELECT authz.unshare(p_type, p_id::text, p_relation, p_subject_type, p_subject_id, p_subject_relation) $$;

-- A link anyone holding the token can use: returns the token once (only its hash is stored).
-- Requests present it with SET LOCAL authz_ctx.links = '<token>'.
CREATE OR REPLACE FUNCTION authz.create_link(p_type text, p_id text, p_relation text, p_expires_at timestamptz DEFAULT NULL)
RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE v_token text := replace(gen_random_uuid()::text || gen_random_uuid()::text, '-', '');
BEGIN
  PERFORM authz.share(p_type, p_id, p_relation, 'link', encode(sha256(convert_to(v_token, 'UTF8')), 'hex'),
                      '', p_expires_at);
  RETURN v_token;
END $f$;
CREATE OR REPLACE FUNCTION authz.create_link(p_type text, p_id bigint, p_relation text, p_expires_at timestamptz DEFAULT NULL)
RETURNS text LANGUAGE sql AS $$ SELECT authz.create_link(p_type, p_id::text, p_relation, p_expires_at) $$;

-- The relations whose links on an object the caller may see: every one it has links of if they may inspect it
-- (they can share it, or are an administrator), else those they may share with a link. NULL: none
CREATE FUNCTION authz_int.link_relations(p_type text, p_id text) RETURNS text[]
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
BEGIN
  IF authz_int.may_inspect(p_type, p_id) THEN
    RETURN coalesce((SELECT array_agg(DISTINCT g.relation) FROM authz.shares g
                     WHERE g.object_type = p_type AND g.object_id = p_id AND g.subject_type = 'link'), '{}');
  END IF;
  RETURN (SELECT array_agg(s.relation) FROM authz_int.shared_relations s
          WHERE s.object_type = p_type AND s.subject = 'link'
            AND authz_int.may_manage(p_type, p_id, s.relation, 'link'));
END $f$;
-- The links on an object: SELECT * FROM authz.list_links('folder', 3). For those who can share it, or may make
-- such links. A link's id names it for authz.revoke_link: it is not the token, and opens nothing.
CREATE OR REPLACE FUNCTION authz.list_links(p_type text, p_id text)
RETURNS TABLE (id text, relation text, created_by text, created_at timestamptz, expires_at timestamptz)
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE v_relations text[];
BEGIN
  p_id := authz_int.canon(p_type, p_id);
  v_relations := authz_int.link_relations(p_type, p_id);
  IF v_relations IS NULL THEN
    RAISE EXCEPTION 'you cannot see the links of % %', p_type, p_id USING ERRCODE = 'insufficient_privilege', HINT = 'rowstile help AZ705';
  END IF;
  RETURN QUERY SELECT left(g.subject_id, 16), g.relation, g.created_by, g.created_at, g.expires_at
  FROM authz.shares g WHERE g.object_type = p_type AND g.object_id = p_id AND g.subject_type = 'link'
    AND g.relation = ANY (v_relations) ORDER BY g.created_at, g.subject_id;
END $f$;
-- Turn a link off, by its id in authz.list_links: needs what unsharing it needs
CREATE OR REPLACE FUNCTION authz.revoke_link(p_type text, p_id text, p_link text) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE v_relations text[]; v record; v_found boolean := false;
BEGIN
  PERFORM authz_int.check_writable();
  p_id := authz_int.canon(p_type, p_id);
  v_relations := authz_int.link_relations(p_type, p_id);
  IF v_relations IS NULL THEN
    RAISE EXCEPTION 'you cannot turn off the links of % %', p_type, p_id USING ERRCODE = 'insufficient_privilege', HINT = 'rowstile help AZ705';
  END IF;
  FOR v IN SELECT g.relation, g.subject_id FROM authz.shares g
           WHERE g.object_type = p_type AND g.object_id = p_id AND g.subject_type = 'link'
             AND g.relation = ANY (v_relations) AND left(g.subject_id, 16) = p_link LOOP
    IF NOT authz_int.may_manage(p_type, p_id, v.relation, 'link') THEN
      RAISE EXCEPTION 'you cannot turn off link % of % % (you could not unshare it)', p_link, p_type, p_id
        USING ERRCODE = 'insufficient_privilege', HINT = 'rowstile help AZ705';
    END IF;
    DELETE FROM authz.shares g WHERE g.object_type = p_type AND g.object_id = p_id AND g.relation = v.relation
      AND g.subject_type = 'link' AND g.subject_id = v.subject_id;
    v_found := true;
  END LOOP;
  IF NOT v_found THEN
    RAISE EXCEPTION 'no link % on % %', p_link, p_type, p_id USING HINT = 'rowstile help AZ708';
  END IF;
END $f$;
CREATE OR REPLACE FUNCTION authz.list_links(p_type text, p_id bigint) RETURNS TABLE (id text, relation text, created_by text, created_at timestamptz, expires_at timestamptz) LANGUAGE sql STABLE AS
  $$ SELECT * FROM authz.list_links(p_type, p_id::text) $$;
CREATE OR REPLACE FUNCTION authz.revoke_link(p_type text, p_id bigint, p_link text) RETURNS void LANGUAGE sql AS
  $$ SELECT authz.revoke_link(p_type, p_id::text, p_link) $$;

-- Custom roles: defined per owner (e.g. an org) by people with 'manage_roles' there
CREATE OR REPLACE FUNCTION authz.create_role(p_owner_type text, p_owner_id text, p_object_type text, p_name text,
  p_permissions text[]) RETURNS bigint LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE v_id bigint; v_bad text;
BEGIN
  PERFORM authz_int.check_writable();
  PERFORM authz_int.users_only('authz.create_role');
  IF NOT EXISTS (SELECT 1 FROM authz_int.perms WHERE type = p_owner_type AND perm = 'manage_roles') THEN
    RAISE EXCEPTION '% has no manage_roles permission in the policy', p_owner_type USING HINT = 'rowstile help AZ707';
  END IF;
  -- a type without `roles` (or one the policy doesn't have): a role there would be one nobody can be given
  IF NOT EXISTS (SELECT 1 FROM authz_int.role_subjects WHERE object_type = p_object_type) THEN
    RAISE EXCEPTION 'no custom roles on % in the policy', p_object_type USING HINT = 'rowstile help AZ707';
  END IF;
  IF authz.uid() IS NULL OR NOT authz.can(p_owner_type, p_owner_id, 'manage_roles') THEN
    RAISE EXCEPTION 'you cannot manage roles of % %', p_owner_type, p_owner_id USING ERRCODE = 'insufficient_privilege', HINT = 'rowstile help AZ705';
  END IF;
  IF p_owner_type IS DISTINCT FROM coalesce(authz_int.role_owner_type(p_object_type), p_owner_type) THEN
    RAISE EXCEPTION 'custom roles on % belong to a % (the policy says where they come from), not to a %',
      p_object_type, authz_int.role_owner_type(p_object_type), p_owner_type USING HINT = 'rowstile help AZ706';
  END IF;
  SELECT string_agg(p, ', ') INTO v_bad FROM unnest(p_permissions) p
  WHERE NOT EXISTS (SELECT 1 FROM authz_int.role_grantable g WHERE g.object_type = p_object_type AND g.permission = p);
  IF v_bad IS NOT NULL THEN
    RAISE EXCEPTION 'custom roles on % cannot grant %', p_object_type, v_bad USING HINT = 'rowstile help AZ706';
  END IF;
  INSERT INTO authz.roles (owner_type, owner_id, object_type, name, created_by)
  VALUES (p_owner_type, authz_int.canon(p_owner_type, p_owner_id), p_object_type, p_name, authz.uid()::text)
  RETURNING id INTO v_id;
  INSERT INTO authz.role_permissions SELECT v_id, p FROM unnest(p_permissions) p ON CONFLICT DO NOTHING;
  RETURN v_id;
END $f$;
CREATE OR REPLACE FUNCTION authz.create_role(p_owner_type text, p_owner_id bigint, p_object_type text, p_name text,
  p_permissions text[]) RETURNS bigint LANGUAGE sql AS
  $$ SELECT authz.create_role(p_owner_type, p_owner_id::text, p_object_type, p_name, p_permissions) $$;
CREATE OR REPLACE FUNCTION authz.set_role_permissions(p_role bigint, p_permissions text[]) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE v authz.roles; v_bad text;
BEGIN
  PERFORM authz_int.check_writable();
  PERFORM authz_int.users_only('authz.set_role_permissions');
  SELECT * INTO v FROM authz.roles WHERE id = p_role;
  IF v.id IS NULL OR authz.uid() IS NULL OR NOT authz.can(v.owner_type, v.owner_id, 'manage_roles') THEN
    RAISE EXCEPTION 'you cannot manage role %', p_role USING ERRCODE = 'insufficient_privilege', HINT = 'rowstile help AZ705';
  END IF;
  SELECT string_agg(p, ', ') INTO v_bad FROM unnest(p_permissions) p
  WHERE NOT EXISTS (SELECT 1 FROM authz_int.role_grantable g WHERE g.object_type = v.object_type AND g.permission = p);
  IF v_bad IS NOT NULL THEN RAISE EXCEPTION 'custom roles on % cannot grant %', v.object_type, v_bad USING HINT = 'rowstile help AZ706'; END IF;
  DELETE FROM authz.role_permissions WHERE role_id = p_role;
  INSERT INTO authz.role_permissions SELECT p_role, p FROM unnest(p_permissions) p ON CONFLICT DO NOTHING;
END $f$;
CREATE OR REPLACE FUNCTION authz.delete_role(p_role bigint) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE v authz.roles;
BEGIN
  PERFORM authz_int.check_writable();
  PERFORM authz_int.users_only('authz.delete_role');
  SELECT * INTO v FROM authz.roles WHERE id = p_role;
  IF v.id IS NULL OR authz.uid() IS NULL OR NOT authz.can(v.owner_type, v.owner_id, 'manage_roles') THEN
    RAISE EXCEPTION 'you cannot manage role %', p_role USING ERRCODE = 'insufficient_privilege', HINT = 'rowstile help AZ705';
  END IF;
  DELETE FROM authz.roles WHERE id = p_role;
END $f$;
CREATE OR REPLACE FUNCTION authz.roles_of(p_owner_type text, p_owner_id text)
RETURNS TABLE (id bigint, object_type text, name text, permissions text[])
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
BEGIN
  PERFORM authz_int.users_only('authz.roles_of');
  IF authz.uid() IS NULL OR NOT (
       (EXISTS (SELECT 1 FROM authz_int.perms WHERE type = p_owner_type AND perm = 'manage_roles')
        AND authz.can(p_owner_type, p_owner_id, 'manage_roles'))
    OR (EXISTS (SELECT 1 FROM authz_int.perms WHERE type = p_owner_type AND perm = 'view')
        AND authz.can(p_owner_type, p_owner_id, 'view'))) THEN
    RAISE EXCEPTION 'you cannot see roles of % %', p_owner_type, p_owner_id USING ERRCODE = 'insufficient_privilege', HINT = 'rowstile help AZ705';
  END IF;
  RETURN QUERY SELECT r.id, r.object_type, r.name,
    ARRAY(SELECT p.permission FROM authz.role_permissions p WHERE p.role_id = r.id ORDER BY 1)
    FROM authz.roles r WHERE r.owner_type = p_owner_type AND r.owner_id = p_owner_id ORDER BY r.id;
END $f$;
CREATE OR REPLACE FUNCTION authz.roles_of(p_owner_type text, p_owner_id bigint)
RETURNS TABLE (id bigint, object_type text, name text, permissions text[]) LANGUAGE sql STABLE AS
  $$ SELECT * FROM authz.roles_of(p_owner_type, p_owner_id::text) $$;

-- Why a write is or would be refused, as the signed-in user: an insert (p_row: the new row as JSON), or an
-- update or delete of the row whose id is p_id (for an update, p_row: the new values). NULL when that row isn't
-- there or the user can't see it (404, not 403). SELECT authz.explain_rule('app.files', 'update', '11')
CREATE OR REPLACE FUNCTION authz.explain_rule(p_table text, p_command text, p_id text DEFAULT NULL, p_row jsonb DEFAULT NULL)
RETURNS text[] LANGUAGE plpgsql STABLE SET search_path = pg_catalog, pg_temp AS $f$
BEGIN
  IF p_command IS NULL OR p_command NOT IN ('insert', 'update', 'delete') THEN
    RAISE EXCEPTION 'explain_rule explains insert, update or delete, not %', p_command USING ERRCODE = 'invalid_parameter_value', HINT = 'rowstile help AZ710';
  END IF;
  CASE p_table
    WHEN 'cx.files' THEN RETURN authz_gen."cx.files:rules:explain"(p_command, p_id, p_row);
    WHEN 'cx.folders' THEN RETURN authz_gen."cx.folders:rules:explain"(p_command, p_id, p_row);
    ELSE RAISE EXCEPTION 'the policy has no rules for table %', p_table USING HINT = 'rowstile help AZ707';
  END CASE;
END $f$;

-- Which of these people (or principals of another type) hold a permission: who to tell about a change.
-- It signs each one in with authz.act_as(), as the caller: so only a backend trusted to sign anyone in can
-- use it, as it could ask authz.can for each one itself. Not in a session limited by scopes or view-as. SELECT * FROM authz.who_among('chat', '7', 'read', ARRAY['1', '2'])
CREATE OR REPLACE FUNCTION authz.who_among(p_type text, p_id text, p_perm text, p_users text[], p_principal_type text DEFAULT 'user')
RETURNS SETOF text LANGUAGE plpgsql VOLATILE SET search_path = pg_catalog, pg_temp AS $f$
DECLARE v_me text := nullif(current_setting('authz.user_id', true), '');
        v_pt text := coalesce(nullif(current_setting('authz.principal_type', true), ''), 'user');
        v_u text;
BEGIN
  IF coalesce(current_setting('authz.scopes', true), '') <> '' OR coalesce(current_setting('authz.acting_user', true), '') <> '' THEN
    RAISE EXCEPTION 'authz.who_among() signs people in, which a session limited by scopes or view-as may not'
      USING ERRCODE = 'insufficient_privilege', HINT = 'rowstile help AZ704';
  END IF;
  BEGIN
    FOREACH v_u IN ARRAY coalesce(p_users, '{}') LOOP
      PERFORM authz.act_as(p_principal_type, v_u);
      IF authz.can(p_type, p_id, p_perm) THEN RETURN NEXT v_u; END IF;
    END LOOP;
  EXCEPTION WHEN OTHERS THEN
    PERFORM authz.act_as(v_pt, v_me);
    RAISE;
  END;
  PERFORM authz.act_as(v_pt, v_me);
END $f$;
CREATE OR REPLACE FUNCTION authz.who_among(p_type text, p_id bigint, p_perm text, p_users text[], p_principal_type text DEFAULT 'user') RETURNS SETOF text LANGUAGE sql VOLATILE AS
  $$ SELECT * FROM authz.who_among(p_type, p_id::text, p_perm, p_users, p_principal_type) $$;

-- these functions call each other; their bodies are checked when first used
SET LOCAL check_function_bodies = off;

CREATE FUNCTION authz_int."user__manager__who"(p_id bigint) RETURNS SETOF bigint
LANGUAGE sql STABLE STRICT SECURITY DEFINER SET search_path FROM CURRENT ROWS 50 AS $f$
  SELECT r."manager_id" FROM "cx"."users" r WHERE r."id" = p_id AND r."manager_id" IS NOT NULL
$f$;

CREATE FUNCTION authz_int."bot__owner__who"(p_id bigint) RETURNS SETOF bigint
LANGUAGE sql STABLE STRICT SECURITY DEFINER SET search_path FROM CURRENT ROWS 50 AS $f$
  SELECT r."owner_id" FROM "cx"."bots" r WHERE r."id" = p_id AND r."owner_id" IS NOT NULL
$f$;

CREATE FUNCTION authz_int."org__admin__who"(p_id bigint) RETURNS SETOF bigint
LANGUAGE sql STABLE STRICT SECURITY DEFINER SET search_path FROM CURRENT ROWS 50 AS $f$
  SELECT s."user_id" FROM "cx"."org_admins" s WHERE s."org_id" = p_id
$f$;

CREATE FUNCTION authz_int."team__lead__who"(p_id text) RETURNS SETOF bigint
LANGUAGE sql STABLE STRICT SECURITY DEFINER SET search_path FROM CURRENT ROWS 50 AS $f$
  SELECT r."lead_id" FROM "cx"."teams" r WHERE (r."org_id", r."slug") = (((p_id)::authz_gen."team__key")."org_id", ((p_id)::authz_gen."team__key")."slug") AND r."lead_id" IS NOT NULL
$f$;

CREATE FUNCTION authz_int."team__member__who"(p_id text) RETURNS SETOF bigint
LANGUAGE sql STABLE STRICT SECURITY DEFINER SET search_path FROM CURRENT ROWS 50 AS $f$
  WITH RECURSIVE gs(id) AS (SELECT p_id UNION SELECT e.subj FROM ((SELECT (CASE WHEN (s."org_id", s."parent_slug") IS NOT NULL THEN ROW(s."org_id"::bigint, s."parent_slug"::text)::text END) AS obj, (CASE WHEN (s."org_id", s."slug") IS NOT NULL THEN ROW(s."org_id"::bigint, s."slug"::text)::text END) AS subj FROM "cx"."teams" s WHERE (CASE WHEN (s."org_id", s."slug") IS NOT NULL THEN ROW(s."org_id"::bigint, s."slug"::text)::text END) IS NOT NULL AND (CASE WHEN (s."org_id", s."parent_slug") IS NOT NULL THEN ROW(s."org_id"::bigint, s."parent_slug"::text)::text END) IS NOT NULL)
  UNION ALL
  (SELECT g.object_id::text AS obj, g.subject_id::text AS subj FROM authz.shares g WHERE g.object_type = 'team' AND g.relation = 'member' AND g.subject_type = 'team' AND g.subject_relation = 'member' AND (g.expires_at IS NULL OR g.expires_at > now()) AND (g.starts_at IS NULL OR g.starts_at <= now()) AND g.caveat IS NULL)) e JOIN gs ON e.obj = gs.id)
  SELECT x FROM gs, LATERAL (SELECT s."user_id" FROM "cx"."team_members" s WHERE (s."org_id", s."team_slug") = (((gs.id)::authz_gen."team__key")."org_id", ((gs.id)::authz_gen."team__key")."slug")) w(x)
$f$;

CREATE FUNCTION authz_int."project__lead__who"(p_id text) RETURNS SETOF bigint
LANGUAGE sql STABLE STRICT SECURITY DEFINER SET search_path FROM CURRENT ROWS 50 AS $f$
  SELECT r."lead_id" FROM "cx"."projects" r WHERE (r."org_id", r."id") = (((p_id)::authz_gen."project__key")."org_id", ((p_id)::authz_gen."project__key")."id") AND r."lead_id" IS NOT NULL
$f$;

CREATE FUNCTION authz_int."folder__owner__who"(p_id text) RETURNS SETOF bigint
LANGUAGE sql STABLE STRICT SECURITY DEFINER SET search_path FROM CURRENT ROWS 50 AS $f$
  SELECT r."owner_id" FROM "cx"."folders" r WHERE (r."org_id", r."id") = (((p_id)::authz_gen."folder__key")."org_id", ((p_id)::authz_gen."folder__key")."id") AND r."owner_id" IS NOT NULL
$f$;

CREATE FUNCTION authz_int."folder__viewer__who"(p_id text) RETURNS SETOF bigint
LANGUAGE sql STABLE STRICT SECURITY DEFINER SET search_path FROM CURRENT ROWS 50 AS $f$
  (SELECT g.subject_id::bigint FROM authz.shares g WHERE g.object_type = 'folder' AND g.object_id = (p_id)::text AND g.relation = 'viewer' AND g.subject_type = 'user' AND g.subject_relation = '' AND g.subject_id <> '*')
  UNION ALL
  (SELECT x FROM authz.shares g, LATERAL authz_int."team__member__who"(g.subject_id::text) x WHERE g.object_type = 'folder' AND g.object_id = (p_id)::text AND g.relation = 'viewer' AND g.subject_type = 'team' AND g.subject_relation = 'member')
$f$;

CREATE FUNCTION authz_int."folder__editor__who"(p_id text) RETURNS SETOF bigint
LANGUAGE sql STABLE STRICT SECURITY DEFINER SET search_path FROM CURRENT ROWS 50 AS $f$
  SELECT x FROM "cx"."folder_teams" s, LATERAL authz_int."team__member__who"((CASE WHEN (s."org_id", s."team_slug") IS NOT NULL THEN ROW(s."org_id"::bigint, s."team_slug"::text)::text END)) x WHERE (s."org_id", s."folder_id") = (((p_id)::authz_gen."folder__key")."org_id", ((p_id)::authz_gen."folder__key")."id")
$f$;

CREATE FUNCTION authz_int."file__owner__who"(p_id text) RETURNS SETOF bigint
LANGUAGE sql STABLE STRICT SECURITY DEFINER SET search_path FROM CURRENT ROWS 50 AS $f$
  SELECT r."owner_id" FROM "cx"."files" r WHERE (r."org_id", r."id") = (((p_id)::authz_gen."file__key")."org_id", ((p_id)::authz_gen."file__key")."id") AND r."owner_id" IS NOT NULL
$f$;

CREATE FUNCTION authz_int."file__uploader__who"(p_id text) RETURNS SETOF bigint
LANGUAGE sql STABLE STRICT SECURITY DEFINER SET search_path FROM CURRENT ROWS 50 AS $f$
