$f$;

CREATE FUNCTION authz_int."user__manager__why"(p_id bigint, p_depth int, p_seen text[])
RETURNS SETOF text LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
DECLARE pad text := repeat('  ', p_depth); v_t record;
BEGIN
  IF p_id IN (SELECT r."id" AS id FROM "cx"."users" r WHERE r."manager_id" = (SELECT authz.uid())) THEN
    RETURN NEXT pad || 'yes  ' || 'manager: manager_id is you' || '';
    RETURN;
  END IF;
  RETURN NEXT pad || 'no   you do not hold user.manager';
END $f$;

CREATE FUNCTION authz_int."user__oversee__why"(p_id bigint, p_depth int, p_seen text[])
RETURNS SETOF text LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
DECLARE pad text := repeat('  ', p_depth); v_ok boolean; v_done boolean := false; v_t record;
        v_holds boolean := p_id IN (SELECT id FROM authz_int."user__oversee");
BEGIN
  IF p_depth > 60 THEN RETURN NEXT pad || '...'; RETURN; END IF;
  RETURN NEXT pad || 'user.oversee = manager or manager.oversee';
  BEGIN
    v_ok := (p_id) IN (SELECT id FROM authz_int."user__manager");
    RETURN NEXT pad || CASE WHEN v_ok THEN 'yes  ' ELSE 'no   ' END || 'manager';
    IF v_ok AND NOT v_done THEN v_done := true; RETURN QUERY SELECT * FROM authz_int."user__manager__why"(p_id, p_depth + 1, p_seen); END IF;
    v_ok := (p_id) IN (SELECT id FROM authz_int."user__manager__oversee");
    RETURN NEXT pad || CASE WHEN v_ok THEN 'yes  ' ELSE 'no   ' END || 'manager.oversee';
    FOR v_t IN SELECT tg.id::text AS id, EXISTS (SELECT 1 FROM authz_int."user__oversee" v WHERE v.id = tg.id) AS ok
               FROM (SELECT r."manager_id" AS id FROM "cx"."users" r WHERE r."id" = p_id AND r."manager_id" IS NOT NULL) tg ORDER BY 2 DESC, 1 LIMIT 5 LOOP
      -- the walk stops at an object the user can't see: nothing about it, or above it
      IF NOT authz_int.visible('user', v_t.id) THEN
        RETURN NEXT pad || '       ' || 'manager is an user you can''t see';
        CONTINUE;
      END IF;
      RETURN NEXT pad || '  ' || CASE WHEN v_t.ok THEN 'yes  ' ELSE 'no   ' END || 'manager is user '
                  || v_t.id || CASE WHEN v_t.ok THEN ', which has oversee' ELSE ', without oversee' END;
      IF NOT ('user:oversee:' || v_t.id = ANY (p_seen)) AND ((v_t.ok AND v_ok AND NOT v_done) OR (NOT v_ok AND NOT v_t.ok AND p_depth < 5)) THEN
        v_done := true; RETURN QUERY SELECT * FROM authz_int."user__oversee__why"(v_t.id::bigint, p_depth + 1 + 1, p_seen || ('user:oversee:' || v_t.id));
      END IF;
    END LOOP;
  END;
END $f$;

CREATE FUNCTION authz_int."bot__owner__why"(p_id bigint, p_depth int, p_seen text[])
RETURNS SETOF text LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
DECLARE pad text := repeat('  ', p_depth); v_t record;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM "cx"."bots" w WHERE w."id" = p_id AND coalesce((w.active), false)) THEN
    RETURN NEXT pad || 'no   bot ' || p_id || ' fails the type''s where {' || 'this.active' || '}';
    RETURN;
  END IF;
